  trashPurgeIntervalMs: envNumber('TEAMNOTES_TRASH_PURGE_INTERVAL_MS', 60 * 60 * 1000),
  maxAttachmentBytes: envNumber('TEAMNOTES_MAX_ATTACHMENT_BYTES', 10 * 1024 * 1024),
