export type Config = typeof config;
export type Db = Database.Database;

export interface AppContext {
  db: Db;
  config: Config;
  publicOrigin(): string;
}

export class HttpError extends Error {
  readonly status: number;

  constructor(status: number, message: string) {
    super(message);
    this.status = status;
  }
}

export function dbFile(c: Config = config): string {
  return path.join(c.dataDir, 'team-notes.db');
}

export function attachmentsDir(c: Config = config): string {
  return path.join(c.dataDir, 'attachments');
}

export function backupsDir(c: Config = config): string {
  return path.join(c.dataDir, 'backups');
