export function migrate(db: Db): void {
  const schema = fs.readFileSync(path.join(here, 'db', 'schema.sql'), 'utf8');
  db.exec(schema);
}

export function openDatabase(file: string = dbFile()): Db {
  fs.mkdirSync(path.dirname(file), { recursive: true });
  const db = new Database(file);
  db.pragma('journal_mode = WAL');
  db.pragma('foreign_keys = ON');
  migrate(db);
  return db;
}

function defaultOrigin(c: Config): string {
  const port = c.httpsPort === 443 ? '' : ':' + c.httpsPort;
  return 'https://' + c.publicHost + port;
}

export function createContext(options: { config?: Config; db?: Db } = {}): AppContext {
  const cfg = options.config ?? config;
  const db = options.db ?? openDatabase(dbFile(cfg));
  return { db, config: cfg, publicOrigin: () => defaultOrigin(cfg) };
}

