function sendClientFile(res: Response, next: NextFunction, root: string, file: string): void {
  res.setHeader('Cache-Control', 'no-cache');
  res.sendFile(file, { root }, (err) => {
    if (err && !res.headersSent) next(new HttpError(404, 'Not found'));
  });
}

export function createApp(ctx: AppContext): express.Express {
  const app = express();
  app.disable('x-powered-by');

  app.use((_req, res, next) => {
    res.setHeader('Strict-Transport-Security', 'max-age=31536000; includeSubDomains');
    next();
  });
  app.use(express.json({ limit: '10mb' }));

  const clientSrc = path.join(repoRoot, 'src', 'client');
  const clientDist = path.join(repoRoot, 'dist', 'client');
  app.get(['/', '/index.html'], (_req, res, next) => sendClientFile(res, next, clientSrc, 'index.html'));
  app.get('/styles.css', (_req, res, next) => sendClientFile(res, next, clientSrc, 'styles.css'));
  app.get('/main.js', (_req, res, next) => sendClientFile(res, next, clientDist, 'main.js'));
  app.get('/main.js.map', (_req, res, next) => sendClientFile(res, next, clientDist, 'main.js.map'));

  app.get('/api/config', (_req, res) => {
    const c = ctx.config;
    res.json({
      autosaveDebounceMs: c.autosaveDebounceMs,
      maxAttachmentBytes: c.maxAttachmentBytes,
      allowedAttachmentExtensions: c.allowedAttachmentExtensions,
      previewableExtensions: c.previewableExtensions,
      trashRetentionDays: c.trashRetentionDays,
      versionIntervalMinutes: c.versionIntervalMinutes,
      versionRetentionCount: c.versionRetentionCount,
      narrowViewportPx: c.narrowViewportPx,
    });
  });

  app.use('/api/auth', authRouter(ctx));
  app.use('/api/preferences', requireSession(ctx), preferencesRouter(ctx));
  app.use('/api/folders', requireSession(ctx), foldersRouter(ctx));
  app.use('/api/tags', requireSession(ctx), tagsRouter(ctx));
  app.use('/api/search', requireSession(ctx), searchRouter(ctx));
  app.use('/api/trash', requireSession(ctx), trashRouter(ctx));
  app.use('/api/attachments', requireSession(ctx), attachmentsRouter(ctx));
  app.use('/api/export', requireSession(ctx), exportRouter(ctx));
  app.use('/api/import', requireSession(ctx), importRouter(ctx));
  app.use(
    '/api/notes',
    requireSession(ctx),
    versionsRouter(ctx),
    noteAttachmentsRouter(ctx),
    noteExportRouter(ctx),
    noteTrashRouter(ctx),
    notesRouter(ctx),
  );

  app.use('/api', (_req, _res, next) => next(new HttpError(404, 'Not found')));
  app.use((_req, _res, next) => next(new HttpError(404, 'Not found')));

  app.use((err: unknown, _req: Request, res: Response, next: NextFunction) => {
    // The full error stays on the server; the client only ever sees a fixed message.
    console.error(err);
    if (res.headersSent) {
      next(err);
      return;
    }
    if (err instanceof HttpError) {
      res.status(err.status).json({ error: err.message });
      return;
    }
    const type = (err as { type?: unknown } | null)?.type;
    if (type === 'entity.parse.failed') {
      res.status(400).json({ error: 'Request body is not valid JSON' });
      return;
    }
    if (type === 'entity.too.large') {
      res.status(413).json({ error: 'Request is too large' });
      return;
    }
    res.status(500).json({ error: 'Something went wrong. Please try again.' });
  });

  return app;
}

export interface RunningServers {
  ctx: AppContext;
  httpsServer: https.Server;
  httpServer: http.Server;
  httpsPort: number;
  httpPort: number;
  stop(): Promise<void>;
}

function listen(server: http.Server | https.Server, port: number, host: string): Promise<void> {
  return new Promise((resolve, reject) => {
    server.once('error', reject);
    server.listen(port, host, () => {
      server.removeListener('error', reject);
      resolve();
    });
  });
}

function closeServer(server: http.Server | https.Server): Promise<void> {
  return new Promise((resolve) => {
    server.close(() => resolve());
    server.closeAllConnections();
  });
}

export async function startServers(
  options: { config?: Config; db?: Db; key?: string | Buffer; cert?: string | Buffer } = {},
): Promise<RunningServers> {
  const ctx = createContext({ config: options.config, db: options.db });
  const cfg = ctx.config;
  const key = options.key ?? fs.readFileSync(cfg.tlsKeyPath);
  const cert = options.cert ?? fs.readFileSync(cfg.tlsCertPath);

  const httpsServer = https.createServer({ key, cert }, createApp(ctx));
  await listen(httpsServer, cfg.httpsPort, cfg.host);
  const httpsPort = (httpsServer.address() as AddressInfo).port;
  ctx.publicOrigin = () => 'https://' + cfg.publicHost + (httpsPort === 443 ? '' : ':' + httpsPort);

  // Plain HTTP only ever answers with a redirect to the configured HTTPS origin.
  const httpServer = http.createServer((req, res) => {
    res.writeHead(301, { Location: ctx.publicOrigin() + (req.url ?? '/'), 'Content-Length': '0' });
    res.end();
  });
  await listen(httpServer, cfg.httpPort, cfg.host);
  const httpPort = (httpServer.address() as AddressInfo).port;

  const purgeTimer = setInterval(() => {
    try {
      jobs.purgeTrash(ctx);
    } catch (err) {
      console.error(err);
    }
  }, cfg.trashPurgeIntervalMs);
  purgeTimer.unref();
  const stopBackups = jobs.startBackupScheduler(ctx);

  return {
    ctx,
    httpsServer,
    httpServer,
    httpsPort,
    httpPort,
    async stop() {
      clearInterval(purgeTimer);
      stopBackups();
      await closeServer(httpServer);
      await closeServer(httpsServer);
      ctx.db.close();
    },
  };
}

const entry = process.argv[1];
if (entry && path.resolve(entry) === path.resolve(fileURLToPath(import.meta.url))) {
  startServers()
    .then((servers) => {
      console.log('Team Notes listening on ' + servers.ctx.publicOrigin());
    })
    .catch((err) => {
      console.error(err);
      process.exit(1);
    });
}
