import { createVersionIfNeeded } from './versions';

export const UNTITLED_LABEL = 'Untitled note';

const PREVIEW_LENGTH = 160;
const MAX_TITLE_LENGTH = 500;
const MAX_BODY_BYTES = 5 * 1024 * 1024;
const MAX_DEPTH = 32;
const MAX_NODES = 100000;
const TAG_CHUNK = 500;

const NODE_TYPES = new Set([
  'doc',
  'paragraph',
  'text',
  'heading',
  'bulletList',
  'orderedList',
  'listItem',
  'taskList',
  'taskItem',
  'blockquote',
  'codeBlock',
  'hardBreak',
  'horizontalRule',
]);
const MARK_TYPES = new Set(['bold', 'italic', 'code', 'strike', 'link']);
const SAFE_LINK = /^(https?:|mailto:)/i;
const TEXT_BLOCKS = new Set(['paragraph', 'heading', 'codeBlock']);

export interface DocNode {
  type: string;
  attrs?: Record<string, unknown>;
  text?: string;
  content?: DocNode[];
  marks?: { type: string; attrs?: Record<string, unknown> }[];
}

export const DEFAULT_BODY: DocNode = { type: 'doc', content: [{ type: 'paragraph' }] };

function fail(): never {
  throw new HttpError(400, 'Note content is not valid');
}

function isRecord(value: unknown): value is Record<string, unknown> {
  return typeof value === 'object' && value !== null && !Array.isArray(value);
}

function validateAttrs(type: string, attrs: unknown): void {
  if (attrs === undefined || attrs === null) return;
  if (!isRecord(attrs)) fail();
  const a = attrs as Record<string, unknown>;
  if (type === 'heading' && a.level !== undefined) {
    if (typeof a.level !== 'number' || !Number.isInteger(a.level) || a.level < 1 || a.level > 6) fail();
  }
  if (type === 'taskItem') {
    if (a.checked !== undefined && typeof a.checked !== 'boolean') fail();
    if (a.item_key !== undefined && (typeof a.item_key !== 'string' || a.item_key.length > 100)) fail();
  }
  if (type === 'orderedList' && a.start !== undefined && !Number.isInteger(a.start)) fail();
  if (type === 'codeBlock' && a.language !== undefined && a.language !== null && typeof a.language !== 'string') {
    fail();
  }
}

function validateMark(mark: unknown): void {
  if (!isRecord(mark)) fail();
  const m = mark as Record<string, unknown>;
  if (typeof m.type !== 'string' || !MARK_TYPES.has(m.type)) fail();
  if (m.type === 'link') {
    const attrs = m.attrs;
    if (!isRecord(attrs)) fail();
    const href = (attrs as Record<string, unknown>).href;
    if (typeof href !== 'string' || href.length > 2048 || !SAFE_LINK.test(href)) fail();
  }
}

function validateNode(node: unknown, depth: number, state: { count: number }): void {
  state.count += 1;
  if (depth > MAX_DEPTH || state.count > MAX_NODES) fail();
  if (!isRecord(node)) fail();
  const n = node as Record<string, unknown>;
  const type = n.type;
  if (typeof type !== 'string' || !NODE_TYPES.has(type)) fail();
  if (type === 'text') {
    if (typeof n.text !== 'string' || n.content !== undefined) fail();
  } else if (n.text !== undefined) {
    fail();
  }
  validateAttrs(type as string, n.attrs);
  if (n.marks !== undefined) {
    if (!Array.isArray(n.marks) || n.marks.length > 20) fail();
    for (const mark of n.marks) validateMark(mark);
  }
  if (n.content !== undefined) {
    if (!Array.isArray(n.content)) fail();
    for (const child of n.content as unknown[]) validateNode(child, depth + 1, state);
  }
}

// Throws a 400 unless the value is a TipTap document using only the allowed node and mark types.
export function validateBodyJson(value: unknown): DocNode {
  if (!isRecord(value) || (value as Record<string, unknown>).type !== 'doc') fail();
  validateNode(value, 0, { count: 0 });
  return value as unknown as DocNode;
}

export function deriveBodyText(doc: DocNode): string {
  const lines: string[] = [];
  let current = '';
  const walk = (node: DocNode): void => {
    if (node.type === 'text') {
      current += node.text ?? '';
      return;
    }
    if (node.type === 'hardBreak') {
      current += '\n';
      return;
    }
    for (const child of node.content ?? []) walk(child);
    if (TEXT_BLOCKS.has(node.type)) {
      lines.push(current);
      current = '';
    }
  };
  walk(doc);
  if (current !== '') lines.push(current);
  while (lines.length > 0 && lines[lines.length - 1] === '') lines.pop();
  return lines.join('\n');
}

interface TaskItem {
  key: string;
  text: string;
  done: boolean;
}

function collectTaskItems(doc: DocNode): TaskItem[] {
  const items: TaskItem[] = [];
  const walk = (node: DocNode): void => {
    if (node.type === 'taskItem') {
      const key = node.attrs?.item_key;
      items.push({
        key: typeof key === 'string' ? key : '',
        text: deriveBodyText({ type: 'doc', content: node.content ?? [] }).replace(/\s+/g, ' ').trim(),
        done: node.attrs?.checked === true,
      });
    }
    for (const child of node.content ?? []) walk(child);
  };
  walk(doc);
  return items;
}

export function syncChecklist(db: Db, userId: string, noteId: string, doc: DocNode): void {
  const used = new Set<string>();
  const rows = collectTaskItems(doc).map((item, position) => {
    let key = item.key;
    if (key === '' || used.has(key)) {
      key = 'pos-' + position;
      while (used.has(key)) key += '_';
    }
    used.add(key);
    return { ...item, key, position };
  });
  const existing = db.prepare('SELECT item_key FROM checklist_items WHERE note_id = ?').all(noteId) as {
    item_key: string;
  }[];
  const remove = db.prepare('DELETE FROM checklist_items WHERE note_id = ? AND item_key = ?');
  for (const row of existing) {
    if (!used.has(row.item_key)) remove.run(noteId, row.item_key);
  }
  const upsert = db.prepare(
    `INSERT INTO checklist_items (id, user_id, note_id, item_key, position, text, done)
     VALUES (?, ?, ?, ?, ?, ?, ?)
     ON CONFLICT(note_id, item_key) DO UPDATE SET
       position = excluded.position, text = excluded.text, done = excluded.done`,
  );
  for (const row of rows) {
    upsert.run(randomUUID(), userId, noteId, row.key, row.position, row.text, row.done ? 1 : 0);
  }
}

export function syncSearchIndex(db: Db, ftsId: number, title: string, bodyText: string): void {
  db.prepare('DELETE FROM notes_fts WHERE rowid = ?').run(ftsId);
  db.prepare('INSERT INTO notes_fts (rowid, title, body_text) VALUES (?, ?, ?)').run(ftsId, title, bodyText);
}

function readTitle(value: unknown): string {
  if (typeof value !== 'string') throw new HttpError(400, 'Title must be text');
  if (value.length > MAX_TITLE_LENGTH) throw new HttpError(400, 'Title is too long');
  return value;
}

function serializeBody(doc: DocNode): string {
  const json = JSON.stringify(doc);
  if (Buffer.byteLength(json, 'utf8') > MAX_BODY_BYTES) throw new HttpError(413, 'Note is too large');
  return json;
}

function displayTitle(title: string): string {
  return title.trim() === '' ? UNTITLED_LABEL : title;
}

export function makePreview(text: string): string {
  return Array.from(text.replace(/\s+/g, ' ').trim()).slice(0, PREVIEW_LENGTH).join('');
}

export interface TagInfo {
  id: string;
  name: string;
  color: string;
}

export function loadTags(db: Db, userId: string, noteIds: string[]): Map<string, TagInfo[]> {
  const map = new Map<string, TagInfo[]>();
  for (let i = 0; i < noteIds.length; i += TAG_CHUNK) {
    const chunk = noteIds.slice(i, i + TAG_CHUNK);
    const marks = chunk.map(() => '?').join(',');
    const rows = db
      .prepare(
        `SELECT nt.note_id, t.id, t.name, t.color
         FROM note_tags nt JOIN tags t ON t.id = nt.tag_id
         WHERE nt.user_id = ? AND t.user_id = ? AND nt.note_id IN (${marks})
         ORDER BY t.name_key`,
      )
      .all(userId, userId, ...chunk) as (TagInfo & { note_id: string })[];
    for (const row of rows) {
      const list = map.get(row.note_id) ?? [];
      list.push({ id: row.id, name: row.name, color: row.color });
      map.set(row.note_id, list);
    }
  }
  return map;
}

export const NOTE_COLUMNS = `n.id, n.title, n.folder_id, n.previous_folder_id, n.pinned, n.created_at, n.updated_at,
  n.archived_at, n.restored_at, n.trashed_at, f.name AS folder_name,
  (SELECT COUNT(*) FROM checklist_items c WHERE c.note_id = n.id) AS checklist_total,
  (SELECT COUNT(*) FROM checklist_items c WHERE c.note_id = n.id AND c.done = 1) AS checklist_done`;

export const NOTE_FROM = `FROM notes n LEFT JOIN folders f ON f.id = n.folder_id AND f.user_id = n.user_id`;

