export function summarize(row: NoteRow, tags: TagInfo[]) {
  return {
    id: row.id,
    title: displayTitle(row.title),
    is_untitled: row.title.trim() === '',
    tags,
    folder_id: row.folder_id,
    folder_name: row.folder_name,
    pinned: row.pinned === 1,
    archived_at: row.archived_at,
    trashed_at: row.trashed_at,
    created_at: row.created_at,
    updated_at: row.updated_at,
    checklist: { total: row.checklist_total, done: row.checklist_done },
  };
}

// Lists summaries for one user. `where` is a trusted SQL fragment over the `n` alias.
export function noteSummaries(db: Db, userId: string, where: string, params: (string | number)[], orderBy: string) {
  const rows = db
    .prepare(
      `SELECT ${NOTE_COLUMNS}, substr(n.body_text, 1, 640) AS preview_source ${NOTE_FROM}
       WHERE n.user_id = ? AND ${where} ORDER BY ${orderBy}`,
    )
    .all(userId, ...params) as (NoteRow & { preview_source: string })[];
  const tags = loadTags(
    db,
    userId,
    rows.map((row) => row.id),
  );
  return rows.map((row) => ({
    ...summarize(row, tags.get(row.id) ?? []),
    preview: makePreview(row.preview_source),
  }));
}

export function loadNote(db: Db, userId: string, noteId: string) {
  const row = db
    .prepare(
      `SELECT ${NOTE_COLUMNS}, n.body_json, n.body_text ${NOTE_FROM} WHERE n.id = ? AND n.user_id = ?`,
    )
    .get(noteId, userId) as (NoteRow & { body_json: string; body_text: string }) | undefined;
  if (!row) throw new HttpError(404, 'Note not found');
  const tags = loadTags(db, userId, [row.id]).get(row.id) ?? [];
  return {
    ...summarize(row, tags),
    raw_title: row.title,
    previous_folder_id: row.previous_folder_id,
    restored_at: row.restored_at,
    body_json: JSON.parse(row.body_json) as DocNode,
    body_text: row.body_text,
  };
}

export function insertNote(
  db: Db,
  userId: string,
  input: { title: string; doc: DocNode; folderId: string | null; pinned?: boolean; now: number },
): string {
  const id = randomUUID();
  const bodyJson = serializeBody(input.doc);
  const bodyText = deriveBodyText(input.doc);
  db.transaction(() => {
    db.prepare(
      `INSERT INTO notes (id, user_id, title, body_json, body_text, folder_id, pinned, created_at, updated_at, fts_id)
       VALUES (?, ?, ?, ?, ?, ?, ?, ?, ?, (SELECT COALESCE(MAX(fts_id), 0) + 1 FROM notes))`,
    ).run(id, userId, input.title, bodyJson, bodyText, input.folderId, input.pinned ? 1 : 0, input.now, input.now);
    const row = db.prepare('SELECT fts_id FROM notes WHERE id = ?').get(id) as { fts_id: number };
    syncSearchIndex(db, row.fts_id, input.title, bodyText);
    syncChecklist(db, userId, id, input.doc);
  })();
  return id;
}

export function queryString(req: Request, name: string): string | undefined {
  const value = req.query[name];
  return typeof value === 'string' && value !== '' ? value : undefined;
}

export function queryFlag(req: Request, name: string): boolean | undefined {
  const value = queryString(req, name);
  if (value === undefined) return undefined;
  if (value === 'true' || value === '1') return true;
  if (value === 'false' || value === '0') return false;
  throw new HttpError(400, 'Filter is not valid');
}

export function queryTime(req: Request, name: string): number | undefined {
  const value = queryString(req, name);
  if (value === undefined) return undefined;
  const time = /^\d+$/.test(value) ? Number(value) : Date.parse(value);
  if (!Number.isFinite(time)) throw new HttpError(400, 'Date range is not valid');
  return time;
}

export function queryInt(req: Request, name: string): number | undefined {
  const value = queryString(req, name);
  if (value === undefined) return undefined;
  if (!/^\d+$/.test(value)) throw new HttpError(400, 'Filter is not valid');
  return Number(value);
}

const DISPLAY_TITLE_SQL = `(CASE WHEN TRIM(n.title) = '' THEN '${UNTITLED_LABEL}' ELSE n.title END) COLLATE NOCASE`;

// Throws unless the note exists for the user and is not in the trash.
function requireLiveNote(db: Db, userId: string, noteId: string): void {
  const row = db.prepare('SELECT trashed_at FROM notes WHERE id = ? AND user_id = ?').get(noteId, userId) as
    | { trashed_at: number | null }
    | undefined;
  if (!row) throw new HttpError(404, 'Note not found');
  if (row.trashed_at !== null) throw new HttpError(409, 'Note is in the trash');
}

function applyAction(
  db: Db,
  userId: string,
  noteId: string,
  now: number,
  assignments: string,
  params: (string | number | null)[],
): void {
  requireLiveNote(db, userId, noteId);
  db.prepare(`UPDATE notes SET ${assignments}, updated_at = ? WHERE id = ? AND user_id = ?`).run(
    ...params,
    now,
    noteId,
    userId,
  );
}

export function notesRouter(ctx: AppContext): Router {
  const router = Router();
  const { db } = ctx;

  router.post('/', (req, res) => {
    const userId = sessionUserId(res);
    const body = req.body ?? {};
    const title = body.title === undefined ? '' : readTitle(body.title);
    const doc = body.body_json === undefined ? DEFAULT_BODY : validateBodyJson(body.body_json);
    let folderId: string | null = null;
    if (body.folder_id !== undefined && body.folder_id !== null) {
      if (typeof body.folder_id !== 'string') throw new HttpError(400, 'Folder is not valid');
      const folder = db.prepare('SELECT id FROM folders WHERE id = ? AND user_id = ?').get(body.folder_id, userId);
      if (!folder) throw new HttpError(404, 'Folder not found');
      folderId = body.folder_id;
    }

    const id = insertNote(db, userId, { title, doc, folderId, now: Date.now() });
    res.status(201).json(loadNote(db, userId, id));
  });

  router.get('/', (req, res) => {
    const userId = sessionUserId(res);

    const sort = queryString(req, 'sort') ?? 'updated';
    const order = queryString(req, 'order') ?? 'desc';
    if (!['updated', 'created', 'title', 'pinned'].includes(sort) || !['asc', 'desc'].includes(order)) {
      throw new HttpError(400, 'Sort is not valid');
    }
    const dir = order === 'asc' ? 'ASC' : 'DESC';
    const orderBy = {
      updated: `n.pinned DESC, n.updated_at ${dir}, n.rowid ${dir}`,
      created: `n.created_at ${dir}, n.rowid ${dir}`,
      title: `${DISPLAY_TITLE_SQL} ${dir}, n.updated_at DESC, n.rowid DESC`,
      pinned: `n.pinned ${dir}, n.updated_at DESC, n.rowid DESC`,
    }[sort as 'updated' | 'created' | 'title' | 'pinned'];

    const folder = queryString(req, 'folder');
    const tag = queryString(req, 'tag');
    const pinned = queryFlag(req, 'pinned');
    const archived = queryFlag(req, 'archived');
    const openTasks = queryFlag(req, 'openTasks');
    const dateField = queryString(req, 'dateField') ?? 'updated';
    if (!['updated', 'created'].includes(dateField)) throw new HttpError(400, 'Date range is not valid');
    const from = queryTime(req, 'from');
    const to = queryTime(req, 'to');
    const limit = queryInt(req, 'limit');
    const offset = queryInt(req, 'offset') ?? 0;

    const where = ['n.user_id = ?', 'n.trashed_at IS NULL'];
    const params: (string | number)[] = [userId];

    // Pinned, Open tasks and tag lists cover archived notes too; every other list is active-only.
    const spansArchived = pinned === true || openTasks === true || tag !== undefined;
    if (archived === true) where.push('n.archived_at IS NOT NULL');
    else if (archived === false || !spansArchived) where.push('n.archived_at IS NULL');

    if (folder !== undefined) {
      if (folder === 'none') {
        where.push('n.folder_id IS NULL');
      } else {
        where.push('n.folder_id = ?');
        params.push(folder);
      }
    }
    if (tag !== undefined) {
      where.push('EXISTS (SELECT 1 FROM note_tags nt WHERE nt.note_id = n.id AND nt.tag_id = ? AND nt.user_id = n.user_id)');
      params.push(tag);
    }
    if (pinned !== undefined) where.push(pinned ? 'n.pinned = 1' : 'n.pinned = 0');
    if (openTasks === true) {
      where.push('EXISTS (SELECT 1 FROM checklist_items c WHERE c.note_id = n.id AND c.done = 0)');
    }
    const dateColumn = dateField === 'created' ? 'n.created_at' : 'n.updated_at';
    if (from !== undefined) {
      where.push(`${dateColumn} >= ?`);
      params.push(from);
    }
    if (to !== undefined) {
      where.push(`${dateColumn} <= ?`);
      params.push(to);
    }

    let sql = `SELECT ${NOTE_COLUMNS}, substr(n.body_text, 1, 640) AS preview_source ${NOTE_FROM}
      WHERE ${where.join(' AND ')} ORDER BY ${orderBy}`;
    if (limit !== undefined) {
      sql += ' LIMIT ? OFFSET ?';
      params.push(limit, offset);
    }
    const rows = db.prepare(sql).all(...params) as (NoteRow & { preview_source: string })[];
    const tags = loadTags(
      db,
      userId,
      rows.map((row) => row.id),
    );
    res.json({
      notes: rows.map((row) => ({
        ...summarize(row, tags.get(row.id) ?? []),
        preview: makePreview(row.preview_source),
      })),
    });
  });

  router.get('/:id/checklist', (req, res) => {
    const userId = sessionUserId(res);
    const noteId = String(req.params.id);
    const note = db.prepare('SELECT id FROM notes WHERE id = ? AND user_id = ?').get(noteId, userId);
    if (!note) throw new HttpError(404, 'Note not found');
    const items = db
      .prepare(
        `SELECT id, item_key, position, text, done FROM checklist_items
         WHERE note_id = ? AND user_id = ? ORDER BY position`,
      )
      .all(noteId, userId) as { id: string; item_key: string; position: number; text: string; done: number }[];
    const done = items.filter((item) => item.done === 1).length;
    res.json({
      items: items.map((item) => ({ ...item, done: item.done === 1 })),
      total: items.length,
      done,
      open: items.length - done,
    });
  });

  router.post('/:id/pin', (req, res) => {
    const userId = sessionUserId(res);
    const noteId = String(req.params.id);
    applyAction(db, userId, noteId, Date.now(), 'pinned = 1', []);
    res.json(loadNote(db, userId, noteId));
  });

  router.post('/:id/unpin', (req, res) => {
    const userId = sessionUserId(res);
    const noteId = String(req.params.id);
    applyAction(db, userId, noteId, Date.now(), 'pinned = 0', []);
    res.json(loadNote(db, userId, noteId));
  });

  router.post('/:id/archive', (req, res) => {
    const userId = sessionUserId(res);
    const noteId = String(req.params.id);
    const now = Date.now();
    applyAction(db, userId, noteId, now, 'archived_at = ?', [now]);
    res.json(loadNote(db, userId, noteId));
  });

  router.post('/:id/unarchive', (req, res) => {
    const userId = sessionUserId(res);
    const noteId = String(req.params.id);
    const now = Date.now();
    applyAction(db, userId, noteId, now, 'restored_at = ?, archived_at = NULL', [now]);
    res.json(loadNote(db, userId, noteId));
  });

  router.put('/:id/folder', (req, res) => {
    const userId = sessionUserId(res);
    const noteId = String(req.params.id);
    const folderId = req.body?.folder_id ?? null;
    if (folderId !== null) {
      if (typeof folderId !== 'string') throw new HttpError(400, 'Folder is not valid');
      const folder = db.prepare('SELECT id FROM folders WHERE id = ? AND user_id = ?').get(folderId, userId);
      if (!folder) throw new HttpError(404, 'Folder not found');
    }
    applyAction(db, userId, noteId, Date.now(), 'folder_id = ?', [folderId]);
    res.json(loadNote(db, userId, noteId));
  });

  router.post('/:id/tags', (req, res) => {
    const userId = sessionUserId(res);
    const noteId = String(req.params.id);
    const body = req.body ?? {};
    requireLiveNote(db, userId, noteId);
    const now = Date.now();
    db.transaction(() => {
      let tagId: string;
      if (body.tag_id !== undefined) {
        if (typeof body.tag_id !== 'string') throw new HttpError(400, 'Tag is not valid');
        const tag = db.prepare('SELECT id FROM tags WHERE id = ? AND user_id = ?').get(body.tag_id, userId) as
          | { id: string }
          | undefined;
        if (!tag) throw new HttpError(404, 'Tag not found');
        tagId = tag.id;
      } else {
        tagId = findOrCreateTag(db, userId, body.name).id;
      }
      db.prepare('INSERT OR IGNORE INTO note_tags (note_id, tag_id, user_id) VALUES (?, ?, ?)').run(noteId, tagId, userId);
      db.prepare('UPDATE notes SET updated_at = ? WHERE id = ? AND user_id = ?').run(now, noteId, userId);
    })();
    res.json(loadNote(db, userId, noteId));
  });

  router.delete('/:id/tags/:tagId', (req, res) => {
    const userId = sessionUserId(res);
    const noteId = String(req.params.id);
    requireLiveNote(db, userId, noteId);
    const now = Date.now();
    db.transaction(() => {
      db.prepare('DELETE FROM note_tags WHERE note_id = ? AND tag_id = ? AND user_id = ?').run(
        noteId,
        String(req.params.tagId),
        userId,
      );
      db.prepare('UPDATE notes SET updated_at = ? WHERE id = ? AND user_id = ?').run(now, noteId, userId);
    })();
    res.json(loadNote(db, userId, noteId));
  });

  router.get('/:id', (req, res) => {
    res.json(loadNote(db, sessionUserId(res), String(req.params.id)));
  });

  router.put('/:id', (req, res) => {
    const userId = sessionUserId(res);
    const noteId = String(req.params.id);
    const body = req.body ?? {};
    const existing = db
      .prepare('SELECT title, body_json, body_text, fts_id, trashed_at FROM notes WHERE id = ? AND user_id = ?')
      .get(noteId, userId) as
      | { title: string; body_json: string; body_text: string; fts_id: number; trashed_at: number | null }
      | undefined;
    if (!existing) throw new HttpError(404, 'Note not found');
    if (existing.trashed_at !== null) throw new HttpError(409, 'Note is in the trash');
    if (body.title === undefined && body.body_json === undefined) {
      throw new HttpError(400, 'Nothing to save');
    }

    const title = body.title === undefined ? existing.title : readTitle(body.title);
    const doc = body.body_json === undefined ? undefined : validateBodyJson(body.body_json);
    const bodyJson = doc ? serializeBody(doc) : undefined;
    const bodyText = doc ? deriveBodyText(doc) : existing.body_text;
    const now = Date.now();

    db.transaction(() => {
      // The pre-change title and body are captured before anything is overwritten.
      createVersionIfNeeded(
        ctx,
        { id: noteId, user_id: userId, title: existing.title, body_json: existing.body_json, body_text: existing.body_text },
        { title, bodyJson, now },
      );
      if (bodyJson !== undefined) {
        db.prepare('UPDATE notes SET title = ?, body_json = ?, body_text = ?, updated_at = ? WHERE id = ? AND user_id = ?').run(
          title,
          bodyJson,
          bodyText,
          now,
          noteId,
          userId,
        );
      } else {
        db.prepare('UPDATE notes SET title = ?, updated_at = ? WHERE id = ? AND user_id = ?').run(
          title,
          now,
          noteId,
          userId,
        );
      }
      syncSearchIndex(db, existing.fts_id, title, bodyText);
      if (doc) syncChecklist(db, userId, noteId, doc);
    })();
    res.json(loadNote(db, userId, noteId));
  });

  return router;
}
"},{"path":"src/server/routes/versions.ts","action":"add","content":"import { randomUUID } from 'node:crypto';
import { Router } from 'express';
import { HttpError, type AppContext, type Db } from '../app';
import { sessionUserId } from '../auth';
import { loadNote, syncChecklist, syncSearchIndex, type DocNode } from './notes';

const PREVIEW_CHARS = 200;

export interface NoteSnapshot {
  id: string;
  user_id: string;
  title: string;
  body_json: string;
  body_text: string;
}

export interface NoteChange {
  title: string;
  bodyJson?: string;
  now: number;
}

function insertVersion(db: Db, snapshot: NoteSnapshot, now: number): void {
  db.prepare(
    `INSERT INTO note_versions (id, user_id, note_id, title, body_json, body_text, created_at)
     VALUES (?, ?, ?, ?, ?, ?, ?)`,
  ).run(randomUUID(), snapshot.user_id, snapshot.id, snapshot.title, snapshot.body_json, snapshot.body_text, now);
}

function pruneVersions(ctx: AppContext, userId: string, noteId: string): void {
  const keep = Math.max(1, Math.floor(ctx.config.versionRetentionCount));
  ctx.db
    .prepare(
      `DELETE FROM note_versions WHERE note_id = ? AND user_id = ? AND id NOT IN (
         SELECT id FROM note_versions WHERE note_id = ? AND user_id = ?
         ORDER BY created_at DESC, rowid DESC LIMIT ?)`,
    )
    .run(noteId, userId, noteId, userId, keep);
}

// OD-004: a change to the title or body stores the pre-change content when the note has no
// version newer than config.versionIntervalMinutes. OD-005: older versions beyond the retention count go.
export function createVersionIfNeeded(ctx: AppContext, noteBefore: NoteSnapshot, change: NoteChange): boolean {
  const titleChanged = change.title !== noteBefore.title;
  const bodyChanged = change.bodyJson !== undefined && change.bodyJson !== noteBefore.body_json;
  if (!titleChanged && !bodyChanged) return false;
  const latest = ctx.db
    .prepare('SELECT MAX(created_at) AS latest FROM note_versions WHERE note_id = ? AND user_id = ?')
    .get(noteBefore.id, noteBefore.user_id) as { latest: number | null };
  const threshold = change.now - ctx.config.versionIntervalMinutes * 60 * 1000;
  if (latest.latest !== null && latest.latest > threshold) return false;
  insertVersion(ctx.db, noteBefore, change.now);
  pruneVersions(ctx, noteBefore.user_id, noteBefore.id);
  return true;
}

export function versionsRouter(ctx: AppContext): Router {
  const router = Router();
  const { db } = ctx;

  router.get('/:id/versions', (req, res) => {
    const userId = sessionUserId(res);
    const noteId = String(req.params.id);
    const note = db.prepare('SELECT id FROM notes WHERE id = ? AND user_id = ?').get(noteId, userId);
    if (!note) throw new HttpError(404, 'Note not found');
    const rows = db
      .prepare(
        `SELECT id, title, created_at, substr(body_text, 1, ${PREVIEW_CHARS}) AS preview
         FROM note_versions WHERE note_id = ? AND user_id = ?
         ORDER BY created_at DESC, rowid DESC`,
      )
      .all(noteId, userId);
    res.json({ versions: rows });
  });

  router.post('/:id/versions/:versionId/restore', (req, res) => {
    const userId = sessionUserId(res);
    const noteId = String(req.params.id);
    const note = db
      .prepare('SELECT id, user_id, title, body_json, body_text, fts_id, trashed_at FROM notes WHERE id = ? AND user_id = ?')
      .get(noteId, userId) as (NoteSnapshot & { fts_id: number; trashed_at: number | null }) | undefined;
    if (!note) throw new HttpError(404, 'Note not found');
    const version = db
      .prepare('SELECT title, body_json, body_text FROM note_versions WHERE id = ? AND note_id = ? AND user_id = ?')
      .get(String(req.params.versionId), noteId, userId) as
      | { title: string; body_json: string; body_text: string }
      | undefined;
    if (!version) throw new HttpError(404, 'Version not found');
    if (note.trashed_at !== null) throw new HttpError(409, 'Note is in the trash');

    const now = Date.now();
    db.transaction(() => {
      // The current content is snapshotted first; no existing version is deleted here.
      insertVersion(db, note, now);
      db.prepare('UPDATE notes SET title = ?, body_json = ?, body_text = ?, updated_at = ? WHERE id = ? AND user_id = ?').run(
        version.title,
        version.body_json,
        version.body_text,
        now,
        noteId,
        userId,
      );
      syncSearchIndex(db, note.fts_id, version.title, version.body_text);
      syncChecklist(db, userId, noteId, JSON.parse(version.body_json) as DocNode);
    })();
    res.json(loadNote(db, userId, noteId));
  });

  return router;
}
"},{"path":"src/server/routes/folders.ts","action":"add","content":"import { randomUUID } from 'node:crypto';
import { Router } from 'express';
import { HttpError, type AppContext, type Db } from '../app';
import { sessionUserId } from '../auth';

const MAX_NAME_LENGTH = 200;

interface FolderRow {
  id: string;
  parent_id: string | null;
  name: string;
  position: number;
  created_at: number;
}

interface FolderNode extends FolderRow {
  note_count: number;
  children: FolderNode[];
}

function readName(value: unknown): string {
  if (typeof value !== 'string') throw new HttpError(400, 'Folder name is required');
  const name = value.trim();
  if (name === '') throw new HttpError(400, 'Folder name is required');
  if (name.length > MAX_NAME_LENGTH) throw new HttpError(400, 'Folder name is too long');
  return name;
}

function subtreeIds(db: Db, userId: string, rootId: string): string[] {
  const rows = db
    .prepare(
      `WITH RECURSIVE sub(id) AS (
         SELECT id FROM folders WHERE id = ? AND user_id = ?
         UNION ALL
         SELECT f.id FROM folders f JOIN sub s ON f.parent_id = s.id WHERE f.user_id = ?
       ) SELECT id FROM sub`,
    )
    .all(rootId, userId, userId) as { id: string }[];
  return rows.map((row) => row.id);
}

function loadTree(db: Db, userId: string) {
  const rows = db
    .prepare(
      `SELECT id, parent_id, name, position, created_at FROM folders
       WHERE user_id = ? ORDER BY position, created_at, id`,
    )
    .all(userId) as FolderRow[];
  const counts = db
    .prepare(
      `SELECT folder_id, COUNT(*) AS count FROM notes
       WHERE user_id = ? AND trashed_at IS NULL AND folder_id IS NOT NULL GROUP BY folder_id`,
    )
    .all(userId) as { folder_id: string; count: number }[];
  const countById = new Map(counts.map((row) => [row.folder_id, row.count]));
  const nodes = new Map<string, FolderNode>();
  for (const row of rows) nodes.set(row.id, { ...row, note_count: countById.get(row.id) ?? 0, children: [] });
  const roots: FolderNode[] = [];
  for (const row of rows) {
    const node = nodes.get(row.id) as FolderNode;
    const parent = row.parent_id ? nodes.get(row.parent_id) : undefined;
    if (parent) parent.children.push(node);
    else roots.push(node);
  }
  return { folders: roots, flat: rows };
}

export function foldersRouter(ctx: AppContext): Router {
  const router = Router();
  const { db } = ctx;

  router.get('/', (_req, res) => {
    res.json(loadTree(db, sessionUserId(res)));
  });

  router.post('/', (req, res) => {
    const userId = sessionUserId(res);
    const name = readName(req.body?.name);
    const parentId = req.body?.parent_id ?? null;
    if (parentId !== null) {
      if (typeof parentId !== 'string') throw new HttpError(400, 'Parent folder is not valid');
      const parent = db.prepare('SELECT id FROM folders WHERE id = ? AND user_id = ?').get(parentId, userId);
      if (!parent) throw new HttpError(404, 'Folder not found');
    }
    const next = db
      .prepare('SELECT COALESCE(MAX(position), -1) + 1 AS position FROM folders WHERE user_id = ? AND parent_id IS ?')
      .get(userId, parentId) as { position: number };
    const id = randomUUID();
    const now = Date.now();
    db.prepare(
      `INSERT INTO folders (id, user_id, parent_id, name, position, created_at, updated_at)
       VALUES (?, ?, ?, ?, ?, ?, ?)`,
    ).run(id, userId, parentId, name, next.position, now, now);
    res.status(201).json({ id, parent_id: parentId, name, position: next.position, created_at: now });
  });

  router.put('/:id', (req, res) => {
    const userId = sessionUserId(res);
    const id = String(req.params.id);
    const name = readName(req.body?.name);
    const result = db
      .prepare('UPDATE folders SET name = ?, updated_at = ? WHERE id = ? AND user_id = ?')
      .run(name, Date.now(), id, userId);
    if (result.changes !== 1) throw new HttpError(404, 'Folder not found');
    const row = db
      .prepare('SELECT id, parent_id, name, position, created_at FROM folders WHERE id = ? AND user_id = ?')
      .get(id, userId);
    res.json(row);
  });

  router.post('/:id/reorder', (req, res) => {
    const userId = sessionUserId(res);
    const id = String(req.params.id);
    const folder = db.prepare('SELECT id, parent_id FROM folders WHERE id = ? AND user_id = ?').get(id, userId) as
      | { id: string; parent_id: string | null }
      | undefined;
    if (!folder) throw new HttpError(404, 'Folder not found');
    const body = req.body ?? {};
    const siblings = db
      .prepare('SELECT id FROM folders WHERE user_id = ? AND parent_id IS ? ORDER BY position, created_at, id')
      .all(userId, folder.parent_id) as { id: string }[];
    const ids = siblings.map((row) => row.id);
    const from = ids.indexOf(id);
    let to: number;
    if (body.direction === 'up') to = from - 1;
    else if (body.direction === 'down') to = from + 1;
    else if (typeof body.position === 'number' && Number.isInteger(body.position)) to = body.position;
    else throw new HttpError(400, 'Position is not valid');
    to = Math.min(Math.max(to, 0), ids.length - 1);
    ids.splice(from, 1);
    ids.splice(to, 0, id);
    const now = Date.now();
    db.transaction(() => {
      const update = db.prepare('UPDATE folders SET position = ?, updated_at = ? WHERE id = ? AND user_id = ?');
      ids.forEach((siblingId, index) => update.run(index, now, siblingId, userId));
    })();
    res.json(loadTree(db, userId));
  });

  router.delete('/:id', (req, res) => {
    const userId = sessionUserId(res);
    const id = String(req.params.id);
    const body = req.body ?? {};
    const disposition = body.disposition ?? req.query.disposition;
    if (disposition !== 'move' && disposition !== 'uncategorize') {
      throw new HttpError(400, 'Choose whether to move the notes or leave them uncategorized');
    }
    const folder = db.prepare('SELECT id FROM folders WHERE id = ? AND user_id = ?').get(id, userId);
    if (!folder) throw new HttpError(404, 'Folder not found');
    const ids = subtreeIds(db, userId, id);

    let targetId: string | null = null;
    if (disposition === 'move') {
      const target = body.target_folder_id ?? req.query.target_folder_id;
      if (typeof target !== 'string' || target === '') throw new HttpError(400, 'Choose a folder to move the notes to');
      const row = db.prepare('SELECT id FROM folders WHERE id = ? AND user_id = ?').get(target, userId);
      if (!row) throw new HttpError(404, 'Folder not found');
      if (ids.includes(target)) throw new HttpError(400, 'The target folder must be outside the folder being deleted');
      targetId = target;
    }

    db.transaction(() => {
      const marks = ids.map(() => '?').join(',');
      // Every non-trashed note, archived ones included, is reassigned; trashed notes keep previous_folder_id.
      db.prepare(
        `UPDATE notes SET folder_id = ? WHERE user_id = ? AND trashed_at IS NULL AND folder_id IN (${marks})`,
      ).run(targetId, userId, ...ids);
      db.prepare(`DELETE FROM folders WHERE user_id = ? AND id IN (${marks})`).run(userId, ...ids);
    })();
    res.json(loadTree(db, userId));
  });

  return router;
}
"},{"path":"src/server/routes/tags.ts","action":"add","content":"import { createHash, randomUUID } from 'node:crypto';
import { Router } from 'express';
import { HttpError, type AppContext, type Db } from '../app';
import { sessionUserId } from '../auth';
import { noteSummaries } from './notes';

const MAX_TAG_LENGTH = 50;

// Every color has at least 4.5:1 contrast against white (#ffffff) text, which is how chips render the name.
export const TAG_PALETTE = [
  '#1d4ed8',
  '#047857',
  '#b91c1c',
  '#7e22ce',
  '#b45309',
  '#0e7490',
  '#be185d',
  '#0f766e',
  '#4d7c0f',
  '#4338ca',
];

// NFKC-normalized, case-folded name used for per-user uniqueness.
export function tagNameKey(name: string): string {
  return name.normalize('NFKC').toUpperCase().toLowerCase().normalize('NFKC');
}

export function readTagName(value: unknown): string {
  if (typeof value !== 'string') throw new HttpError(400, 'Tag name is required');
  const name = value.trim().replace(/\s+/g, ' ');
  if (name === '') throw new HttpError(400, 'Tag name is required');
  if (name.length > MAX_TAG_LENGTH) throw new HttpError(400, 'Tag name is too long');
  return name;
}

export interface TagResult {
  id: string;
  name: string;
  color: string;
  created: boolean;
}

// Reuses the user's tag whose key matches, otherwise creates one with a palette color.
export function findOrCreateTag(db: Db, userId: string, rawName: unknown): TagResult {
  const name = readTagName(rawName);
  const key = tagNameKey(name);
  const existing = db
    .prepare('SELECT id, name, color FROM tags WHERE user_id = ? AND name_key = ?')
    .get(userId, key) as { id: string; name: string; color: string } | undefined;
  if (existing) return { ...existing, created: false };
  const count = (db.prepare('SELECT COUNT(*) AS count FROM tags WHERE user_id = ?').get(userId) as { count: number })
    .count;
  const offset = createHash('sha1').update(key).digest()[0];
  const color = TAG_PALETTE[(count + offset) % TAG_PALETTE.length];
  const id = randomUUID();
  db.prepare('INSERT INTO tags (id, user_id, name, name_key, color, created_at) VALUES (?, ?, ?, ?, ?, ?)').run(
    id,
    userId,
    name,
    key,
    color,
    Date.now(),
  );
  return { id, name, color, created: true };
}

export function tagsRouter(ctx: AppContext): Router {
  const router = Router();
  const { db } = ctx;

  router.get('/', (_req, res) => {
    const userId = sessionUserId(res);
    const tags = db
      .prepare(
        `SELECT t.id, t.name, t.color,
           (SELECT COUNT(*) FROM note_tags nt JOIN notes n ON n.id = nt.note_id
            WHERE nt.tag_id = t.id AND n.user_id = t.user_id AND n.trashed_at IS NULL) AS note_count
         FROM tags t WHERE t.user_id = ? ORDER BY t.name_key`,
      )
      .all(userId);
    res.json({ tags });
  });

  router.post('/', (req, res) => {
    const userId = sessionUserId(res);
    const tag = findOrCreateTag(db, userId, req.body?.name);
    const { created, ...rest } = tag;
    res.status(created ? 201 : 200).json(rest);
  });

  const update = (req: import('express').Request, res: import('express').Response): void => {
    const userId = sessionUserId(res);
    const id = String(req.params.id);
    const body = req.body ?? {};
    const tag = db.prepare('SELECT id, name, color FROM tags WHERE id = ? AND user_id = ?').get(id, userId) as
      | { id: string; name: string; color: string }
      | undefined;
    if (!tag) throw new HttpError(404, 'Tag not found');
    if (body.name === undefined && body.color === undefined) throw new HttpError(400, 'Nothing to change');
    let name = tag.name;
    let key: string | undefined;
    let color = tag.color;
    if (body.name !== undefined) {
      name = readTagName(body.name);
      key = tagNameKey(name);
      const clash = db
        .prepare('SELECT id FROM tags WHERE user_id = ? AND name_key = ? AND id <> ?')
        .get(userId, key, id);
      if (clash) throw new HttpError(409, 'A tag with that name already exists');
    }
    if (body.color !== undefined) {
      if (typeof body.color !== 'string' || !TAG_PALETTE.includes(body.color.toLowerCase())) {
        throw new HttpError(400, 'Choose one of the available tag colors');
      }
      color = body.color.toLowerCase();
    }
    if (key !== undefined) {
      db.prepare('UPDATE tags SET name = ?, name_key = ?, color = ? WHERE id = ? AND user_id = ?').run(
        name,
        key,
        color,
        id,
        userId,
      );
    } else {
      db.prepare('UPDATE tags SET color = ? WHERE id = ? AND user_id = ?').run(color, id, userId);
    }
    res.json({ id, name, color });
  };
  router.put('/:id', update);
  router.patch('/:id', update);

  router.delete('/:id', (req, res) => {
    const userId = sessionUserId(res);
    const id = String(req.params.id);
    const tag = db.prepare('SELECT id FROM tags WHERE id = ? AND user_id = ?').get(id, userId);
    if (!tag) throw new HttpError(404, 'Tag not found');
    db.transaction(() => {
      db.prepare('DELETE FROM note_tags WHERE tag_id = ? AND user_id = ?').run(id, userId);
      db.prepare('DELETE FROM tags WHERE id = ? AND user_id = ?').run(id, userId);
    })();
    res.json({ ok: true });
  });

  router.get('/:id/notes', (req, res) => {
    const userId = sessionUserId(res);
    const id = String(req.params.id);
    const tag = db.prepare('SELECT id FROM tags WHERE id = ? AND user_id = ?').get(id, userId);
    if (!tag) throw new HttpError(404, 'Tag not found');
    // The tag list covers every note that is not trashed, archived notes included.
    const notes = noteSummaries(
      db,
      userId,
      `n.trashed_at IS NULL AND EXISTS (
         SELECT 1 FROM note_tags nt WHERE nt.note_id = n.id AND nt.tag_id = ? AND nt.user_id = n.user_id)`,
      [id],
      'n.pinned DESC, n.updated_at DESC, n.rowid DESC',
    );
    res.json({ notes });
  });

  return router;
}
"},{"path":"src/server/routes/search.ts","action":"add","content":"import { Router } from 'express';
import { HttpError, type AppContext } from '../app';
import { sessionUserId } from '../auth';
import {
  NOTE_COLUMNS,
  loadTags,
  makePreview,
  queryFlag,
  queryInt,
  queryString,
  queryTime,
  summarize,
  type NoteRow,
} from './notes';

const DEFAULT_LIMIT = 200;
const MAX_LIMIT = 1000;
const MAX_TOKENS = 20;

const STATUS_CLAUSES: Record<string, string> = {
  active: '(n.trashed_at IS NULL AND n.archived_at IS NULL)',
  archived: '(n.trashed_at IS NULL AND n.archived_at IS NOT NULL)',
  trashed: '(n.trashed_at IS NOT NULL)',
};

export function searchRouter(ctx: AppContext): Router {
  const router = Router();
  const { db } = ctx;

  router.get('/', (req, res) => {
    const userId = sessionUserId(res);
    const q = queryString(req, 'q') ?? '';
    const tokens = (q.match(/[\p{L}\p{N}_]+/gu) ?? []).slice(0, MAX_TOKENS);
    if (tokens.length === 0) {
      res.json({ results: [] });
      return;
    }
    // Every token is quoted so user input can never be read as FTS5 syntax; each also matches as a prefix.
    const match = tokens.map((token) => '"' + token + '"*').join(' ');

    const folder = queryString(req, 'folder');
    const tag = queryString(req, 'tag');
    const hasAttachments = queryFlag(req, 'hasAttachments');
    const dateField = queryString(req, 'dateField') ?? 'updated';
    if (!['updated', 'created'].includes(dateField)) throw new HttpError(400, 'Date range is not valid');
    const from = queryTime(req, 'from');
    const to = queryTime(req, 'to');
    const limit = Math.min(queryInt(req, 'limit') ?? DEFAULT_LIMIT, MAX_LIMIT);

    const rawStatus = queryString(req, 'status');
    const statuses = rawStatus ? rawStatus.split(',') : ['active', 'archived'];
    if (!statuses.every((status) => status in STATUS_CLAUSES)) throw new HttpError(400, 'Status is not valid');

    const where = ['notes_fts MATCH ?', 'n.user_id = ?'];
    const params: (string | number)[] = [match, userId];
    where.push('(' + statuses.map((status) => STATUS_CLAUSES[status]).join(' OR ') + ')');
    if (folder !== undefined) {
      if (folder === 'none') {
        where.push('n.folder_id IS NULL');
      } else {
        where.push('n.folder_id = ?');
        params.push(folder);
      }
    }
    if (tag !== undefined) {
      where.push('EXISTS (SELECT 1 FROM note_tags nt WHERE nt.note_id = n.id AND nt.tag_id = ? AND nt.user_id = n.user_id)');
      params.push(tag);
    }
    if (hasAttachments !== undefined) {
      where.push(
        (hasAttachments ? 'EXISTS' : 'NOT EXISTS') +
          ' (SELECT 1 FROM attachments a WHERE a.note_id = n.id AND a.user_id = n.user_id)',
      );
    }
    const dateColumn = dateField === 'created' ? 'n.created_at' : 'n.updated_at';
    if (from !== undefined) {
      where.push(dateColumn + ' >= ?');
      params.push(from);
    }
    if (to !== undefined) {
      where.push(dateColumn + ' <= ?');
      params.push(to);
    }

    const rows = db
      .prepare(
        `SELECT ${NOTE_COLUMNS},
           snippet(notes_fts, -1, '', '', '…', 16) AS snippet,
           substr(n.body_text, 1, 640) AS preview_source
         FROM notes_fts
         JOIN notes n ON n.fts_id = notes_fts.rowid
         LEFT JOIN folders f ON f.id = n.folder_id AND f.user_id = n.user_id
         WHERE ${where.join(' AND ')}
         ORDER BY bm25(notes_fts), n.updated_at DESC, n.rowid DESC
         LIMIT ?`,
      )
      .all(...params, limit) as (NoteRow & { snippet: string; preview_source: string })[];
    const tags = loadTags(
      db,
      userId,
      rows.map((row) => row.id),
    );
    res.json({
      results: rows.map((row) => {
        const preview = makePreview(row.preview_source);
        return {
          ...summarize(row, tags.get(row.id) ?? []),
          preview,
          snippet: row.snippet === '' ? preview : row.snippet,
        };
      }),
    });
  });

  return router;
}
"},{"path":"src/server/routes/trash.ts","action":"add","content":"import fs from 'node:fs';
import { Router } from 'express';
import { HttpError, type AppContext } from '../app';
import { sessionUserId } from '../auth';
import { attachmentFilePath } from './attachments';
import { loadNote, noteSummaries } from './notes';

const DAY_MS = 24 * 60 * 60 * 1000;

function retentionCutoff(ctx: AppContext, now: number): number {
  return now - ctx.config.trashRetentionDays * DAY_MS;
}

// Deletes the note and everything that hangs off it, then its attachment files.
export function hardDeleteNote(ctx: AppContext, userId: string, noteId: string): boolean {
  const { db } = ctx;
  const keys: string[] = [];
  const removed = db.transaction(() => {
    const note = db.prepare('SELECT fts_id FROM notes WHERE id = ? AND user_id = ?').get(noteId, userId) as
      | { fts_id: number }
      | undefined;
    if (!note) return false;
    const rows = db.prepare('SELECT storage_key FROM attachments WHERE note_id = ? AND user_id = ?').all(noteId, userId) as {
      storage_key: string;
    }[];
    for (const row of rows) keys.push(row.storage_key);
    db.prepare('DELETE FROM note_versions WHERE note_id = ? AND user_id = ?').run(noteId, userId);
    db.prepare('DELETE FROM checklist_items WHERE note_id = ? AND user_id = ?').run(noteId, userId);
    db.prepare('DELETE FROM note_tags WHERE note_id = ? AND user_id = ?').run(noteId, userId);
    db.prepare('DELETE FROM attachments WHERE note_id = ? AND user_id = ?').run(noteId, userId);
    db.prepare('DELETE FROM notes_fts WHERE rowid = ?').run(note.fts_id);
    db.prepare('DELETE FROM notes WHERE id = ? AND user_id = ?').run(noteId, userId);
    return true;
  })();
  for (const key of keys) {
    try {
      fs.rmSync(attachmentFilePath(ctx.config, key), { force: true });
    } catch (err) {
      console.error(err);
    }
  }
  return removed;
}

// Hard-deletes every note trashed at or before the retention cutoff; called by the app.ts timer.
export function purgeExpiredTrash(ctx: AppContext): number {
  const cutoff = retentionCutoff(ctx, Date.now());
  const rows = ctx.db
    .prepare('SELECT id, user_id FROM notes WHERE trashed_at IS NOT NULL AND trashed_at <= ?')
    .all(cutoff) as { id: string; user_id: string }[];
  let purged = 0;
  for (const row of rows) {
    if (hardDeleteNote(ctx, row.user_id, row.id)) purged += 1;
  }
  return purged;
}

export function noteTrashRouter(ctx: AppContext): Router {
  const router = Router();
  const { db } = ctx;

  router.post('/:id/trash', (req, res) => {
    const userId = sessionUserId(res);
    const noteId = String(req.params.id);
    const note = db.prepare('SELECT trashed_at FROM notes WHERE id = ? AND user_id = ?').get(noteId, userId) as
      | { trashed_at: number | null }
      | undefined;
    if (!note) throw new HttpError(404, 'Note not found');
    if (note.trashed_at !== null) throw new HttpError(409, 'Note is already in the trash');
    const now = Date.now();
    db.prepare(
      'UPDATE notes SET trashed_at = ?, updated_at = ?, previous_folder_id = folder_id WHERE id = ? AND user_id = ?',
    ).run(now, now, noteId, userId);
    res.json(loadNote(db, userId, noteId));
  });

  return router;
}

export function trashRouter(ctx: AppContext): Router {
  const router = Router();
  const { db } = ctx;

  router.get('/', (_req, res) => {
    const userId = sessionUserId(res);
    const cutoff = retentionCutoff(ctx, Date.now());
    const notes = noteSummaries(db, userId, 'n.trashed_at IS NOT NULL AND n.trashed_at > ?', [cutoff], 'n.trashed_at DESC, n.rowid DESC');
    res.json({
      notes: notes.map((note) => ({
        ...note,
        expires_at: (note.trashed_at as number) + ctx.config.trashRetentionDays * DAY_MS,
      })),
    });
  });

  router.post('/:id/restore', (req, res) => {
    const userId = sessionUserId(res);
    const noteId = String(req.params.id);
    const now = Date.now();
    const note = db
      .prepare(
        'SELECT previous_folder_id FROM notes WHERE id = ? AND user_id = ? AND trashed_at IS NOT NULL AND trashed_at > ?',
      )
      .get(noteId, userId, retentionCutoff(ctx, now)) as { previous_folder_id: string | null } | undefined;
    if (!note) throw new HttpError(404, 'Note not found');
    let folderId: string | null = null;
    if (note.previous_folder_id !== null) {
      const folder = db
        .prepare('SELECT id FROM folders WHERE id = ? AND user_id = ?')
        .get(note.previous_folder_id, userId);
      if (folder) folderId = note.previous_folder_id;
    }
    db.prepare(
      'UPDATE notes SET trashed_at = NULL, restored_at = ?, updated_at = ?, folder_id = ? WHERE id = ? AND user_id = ?',
    ).run(now, now, folderId, noteId, userId);
    res.json(loadNote(db, userId, noteId));
  });

  router.delete('/:id', (req, res) => {
    const userId = sessionUserId(res);
    const noteId = String(req.params.id);
    const note = db
      .prepare('SELECT id FROM notes WHERE id = ? AND user_id = ? AND trashed_at IS NOT NULL')
      .get(noteId, userId);
    if (!note) throw new HttpError(404, 'Note not found');
    hardDeleteNote(ctx, userId, noteId);
    res.json({ ok: true });
  });

  return router;
}
"},{"path":"src/server/routes/attachments.ts","action":"add","content":"import { randomUUID } from 'node:crypto';
import fs from 'node:fs';
import path from 'node:path';
import type { Readable } from 'node:stream';
import { pipeline } from 'node:stream/promises';
import busboy from 'busboy';
import { Router, type Request } from 'express';
import { HttpError, attachmentsDir, tmpDir, type AppContext, type Config, type Db } from '../app';
import { sessionUserId } from '../auth';

export const TYPE_ERROR = 'File type is not supported';

const HEAD_BYTES = 8192;

interface TypeRule {
  mime: string;
  check: (head: Uint8Array) => boolean;
}

function startsWith(head: Uint8Array, bytes: number[], offset = 0): boolean {
  if (head.length < offset + bytes.length) return false;
  return bytes.every((byte, index) => head[offset + index] === byte);
}

function ascii(text: string): number[] {
  return Array.from(text).map((char) => char.charCodeAt(0));
}

function looksLikeText(head: Uint8Array): boolean {
  if (head.includes(0)) return false;
  try {
    new TextDecoder('utf-8', { fatal: true }).decode(head, { stream: true });
    return true;
  } catch {
    return false;
  }
}

const jpeg: TypeRule = { mime: 'image/jpeg', check: (head) => startsWith(head, [0xff, 0xd8, 0xff]) };

const TYPE_RULES: Record<string, TypeRule> = {
  png: { mime: 'image/png', check: (head) => startsWith(head, [0x89, 0x50, 0x4e, 0x47, 0x0d, 0x0a, 0x1a, 0x0a]) },
  jpg: jpeg,
  jpeg,
  gif: {
    mime: 'image/gif',
    check: (head) => startsWith(head, ascii('GIF87a')) || startsWith(head, ascii('GIF89a')),
  },
  webp: {
    mime: 'image/webp',
    check: (head) => startsWith(head, ascii('RIFF')) && startsWith(head, ascii('WEBP'), 8),
  },
  pdf: { mime: 'application/pdf', check: (head) => startsWith(head, ascii('%PDF-')) },
  txt: { mime: 'text/plain', check: looksLikeText },
  md: { mime: 'text/markdown', check: looksLikeText },
};

export function attachmentExtension(fileName: string): string {
  const dot = fileName.lastIndexOf('.');
  return dot > 0 ? fileName.slice(dot + 1).toLowerCase() : '';
}

// Returns the extension and mime when the extension is allowed and the leading bytes agree with it.
export function checkAttachmentType(cfg: Config, fileName: string, head: Uint8Array): { ext: string; mime: string } | null {
  const ext = attachmentExtension(fileName);
  const rule = TYPE_RULES[ext];
  if (!rule || !cfg.allowedAttachmentExtensions.includes(ext)) return null;
  return rule.check(head) ? { ext, mime: rule.mime } : null;
}

export function extensionAllowed(cfg: Config, fileName: string): boolean {
  const ext = attachmentExtension(fileName);
  return ext in TYPE_RULES && cfg.allowedAttachmentExtensions.includes(ext);
}

function formatBytes(bytes: number): string {
  if (bytes >= 1024 * 1024) {
    const mb = bytes / (1024 * 1024);
    return (Number.isInteger(mb) ? String(mb) : String(Number(mb.toFixed(1)))) + ' MB';
  }
  if (bytes >= 1024) return String(Number((bytes / 1024).toFixed(1))) + ' KB';
  return bytes + ' bytes';
}

export function sizeLimitMessage(cfg: Config): string {
  return 'File exceeds the ' + formatBytes(cfg.maxAttachmentBytes) + ' size limit';
}

export function attachmentFilePath(cfg: Config, storageKey: string): string {
  return path.join(attachmentsDir(cfg), storageKey);
}

export function contentDisposition(type: 'attachment' | 'inline', fileName: string): string {
  const fallback = fileName.replace(/[^\x20-\x7e]/g, '_').replace(/["\\]/g, '_');
  const encoded = encodeURIComponent(fileName).replace(
    /['()*]/g,
    (char) => '%' + char.charCodeAt(0).toString(16).toUpperCase(),
  );
  return type + '; filename="' + fallback + '"; filename*=UTF-8\'\'' + encoded;
}

function cleanFileName(raw: string): string {
  const base = path.posix.basename(raw.replace(/\\/g, '/'));
  const printable = Array.from(base)
    .filter((char) => char.charCodeAt(0) >= 32 && char.charCodeAt(0) !== 127)
    .join('')
    .trim();
  return printable.slice(0, 255);
}

interface Upload {
  tmpPath: string;
  fileName: string;
  size: number;
}

// Streams the single uploaded file to a temporary file; any rejection removes that file.
function receiveUpload(req: Request, cfg: Config): Promise<Upload> {
  return new Promise<Upload>((resolve, reject) => {
    let settled = false;
    let failure: HttpError | undefined;
    let tmpPath: string | undefined;
    let out: fs.WriteStream | undefined;
    let fileName = '';
    let seen = false;
    let size = 0;
    let written: Promise<void> = Promise.resolve();

    const finish = (err?: HttpError, upload?: Upload): void => {
      if (settled) return;
      settled = true;
      if (err || !upload) {
        const target = tmpPath;
        void written.then(async () => {
          if (target) await fs.promises.rm(target, { force: true }).catch(() => undefined);
          reject(err ?? new HttpError(400, 'Upload is not valid'));
        });
        return;
      }
      resolve(upload);
    };

    let bb: busboy.Busboy;
    try {
      bb = busboy({
        headers: req.headers,
        defParamCharset: 'utf8',
        limits: { files: 1, fileSize: cfg.maxAttachmentBytes, fields: 5, parts: 10 },
      });
    } catch {
      reject(new HttpError(400, 'Upload is not valid'));
      return;
    }

    bb.on('file', (_field, stream: Readable, info) => {
      if (seen || failure) {
        stream.resume();
        return;
      }
      seen = true;
      fileName = cleanFileName(info.filename ?? '');
      if (fileName === '' || !extensionAllowed(cfg, fileName)) {
        failure = new HttpError(415, TYPE_ERROR);
        stream.resume();
        return;
      }
      fs.mkdirSync(tmpDir(cfg), { recursive: true });
      const target = path.join(tmpDir(cfg), randomUUID() + '.part');
      tmpPath = target;
      const sink = fs.createWriteStream(target);
      out = sink;
      written = new Promise<void>((done) => {
        sink.on('close', () => done());
      });
      sink.on('error', () => {
        failure ??= new HttpError(500, 'Something went wrong. Please try again.');
      });
      stream.on('data', (chunk: Buffer) => {
        size += chunk.length;
      });
      stream.on('limit', () => {
        // Past the size limit: stop writing, keep draining the request.
        failure ??= new HttpError(413, sizeLimitMessage(cfg));
        stream.unpipe(sink);
        sink.destroy();
        stream.resume();
      });
      stream.pipe(sink);
    });
    bb.on('filesLimit', () => {
      failure ??= new HttpError(400, 'Upload one file at a time');
    });
    bb.on('error', () => {
      failure ??= new HttpError(400, 'Upload is not valid');
    });
    bb.on('close', () => {
      void written.then(() => {
        if (failure) {
          finish(failure);
        } else if (!seen || !tmpPath) {
          finish(new HttpError(400, 'No file was uploaded'));
        } else {
          finish(undefined, { tmpPath, fileName, size });
        }
      });
    });
    req.on('error', () => {
      out?.destroy();
      finish(new HttpError(400, 'Upload was interrupted'));
    });
    req.on('close', () => {
      if (!req.complete) {
        out?.destroy();
        finish(new HttpError(400, 'Upload was interrupted'));
      }
    });
    req.pipe(bb);
  });
}

async function readHead(file: string): Promise<Uint8Array> {
  const handle = await fs.promises.open(file, 'r');
  try {
    const buffer = Buffer.alloc(HEAD_BYTES);
    const { bytesRead } = await handle.read(buffer, 0, HEAD_BYTES, 0);
    return buffer.subarray(0, bytesRead);
  } finally {
    await handle.close();
  }
}

interface AttachmentRow {
  id: string;
  file_name: string;
  mime: string;
  size: number;
  storage_key: string;
  uploaded_at: number;
}

function describe(cfg: Config, row: AttachmentRow) {
  const ext = attachmentExtension(row.file_name);
  return {
    id: row.id,
    file_name: row.file_name,
    mime: row.mime,
    size: row.size,
    uploaded_at: row.uploaded_at,
    previewable: cfg.previewableExtensions.includes(ext) && row.mime.startsWith('image/'),
  };
}

function loadAttachment(db: Db, userId: string, id: string): AttachmentRow {
  const row = db
    .prepare(
      'SELECT id, file_name, mime, size, storage_key, uploaded_at FROM attachments WHERE id = ? AND user_id = ?',
    )
    .get(id, userId) as AttachmentRow | undefined;
  if (!row) throw new HttpError(404, 'Attachment not found');
  return row;
}

export function noteAttachmentsRouter(ctx: AppContext): Router {
  const router = Router();
  const { db, config } = ctx;

  router.post('/:id/attachments', async (req, res) => {
    const userId = sessionUserId(res);
    const noteId = String(req.params.id);
    const note = db.prepare('SELECT trashed_at FROM notes WHERE id = ? AND user_id = ?').get(noteId, userId) as
      | { trashed_at: number | null }
      | undefined;
    if (!note) throw new HttpError(404, 'Note not found');
    if (note.trashed_at !== null) throw new HttpError(409, 'Note is in the trash');
    if (!/^multipart\/form-data/i.test(req.headers['content-type'] ?? '')) {
      throw new HttpError(400, 'Upload is not valid');
    }

    const upload = await receiveUpload(req, config);
    try {
      const type = checkAttachmentType(config, upload.fileName, await readHead(upload.tmpPath));
      if (!type) throw new HttpError(415, TYPE_ERROR);
      const key = randomUUID();
      const dest = attachmentFilePath(config, key);
      fs.mkdirSync(attachmentsDir(config), { recursive: true });
      fs.renameSync(upload.tmpPath, dest);
      const id = randomUUID();
      const uploadedAt = Date.now();
      try {
        db.prepare(
          `INSERT INTO attachments (id, user_id, note_id, file_name, mime, size, storage_key, uploaded_at)
           VALUES (?, ?, ?, ?, ?, ?, ?, ?)`,
        ).run(id, userId, noteId, upload.fileName, type.mime, upload.size, key, uploadedAt);
      } catch (err) {
        fs.rmSync(dest, { force: true });
        throw err;
      }
      res.status(201).json(
        describe(config, {
          id,
          file_name: upload.fileName,
          mime: type.mime,
          size: upload.size,
          storage_key: key,
          uploaded_at: uploadedAt,
        }),
      );
    } catch (err) {
      await fs.promises.rm(upload.tmpPath, { force: true }).catch(() => undefined);
      throw err;
    }
  });

  router.get('/:id/attachments', (req, res) => {
    const userId = sessionUserId(res);
    const noteId = String(req.params.id);
    const note = db.prepare('SELECT id FROM notes WHERE id = ? AND user_id = ?').get(noteId, userId);
    if (!note) throw new HttpError(404, 'Note not found');
    const rows = db
      .prepare(
        `SELECT id, file_name, mime, size, storage_key, uploaded_at FROM attachments
         WHERE note_id = ? AND user_id = ? ORDER BY uploaded_at, rowid`,
      )
      .all(noteId, userId) as AttachmentRow[];
    res.json({ attachments: rows.map((row) => describe(config, row)) });
  });

  return router;
}

async function sendStoredFile(res: import('express').Response, cfg: Config, row: AttachmentRow, headers: Record<string, string>): Promise<void> {
  const file = attachmentFilePath(cfg, row.storage_key);
  let stat: fs.Stats;
  try {
    stat = fs.statSync(file);
  } catch {
    throw new HttpError(404, 'Attachment not found');
  }
  res.setHeader('Content-Type', row.mime);
  res.setHeader('Content-Length', String(stat.size));
  res.setHeader('X-Content-Type-Options', 'nosniff');
  res.setHeader('Cache-Control', 'private, no-store');
  for (const [name, value] of Object.entries(headers)) res.setHeader(name, value);
  await pipeline(fs.createReadStream(file), res);
}

export function attachmentsRouter(ctx: AppContext): Router {
  const router = Router();
  const { db, config } = ctx;

  router.get('/:id/download', async (req, res) => {
    const row = loadAttachment(db, sessionUserId(res), String(req.params.id));
    await sendStoredFile(res, config, row, { 'Content-Disposition': contentDisposition('attachment', row.file_name) });
  });

  router.get('/:id/preview', async (req, res) => {
    const row = loadAttachment(db, sessionUserId(res), String(req.params.id));
    const previewable =
      config.previewableExtensions.includes(attachmentExtension(row.file_name)) && row.mime.startsWith('image/');
    if (!previewable) throw new HttpError(404, 'Preview is not available');
    await sendStoredFile(res, config, row, {
      'Content-Disposition': 'inline',
      'Content-Security-Policy': "default-src 'none'; sandbox",
    });
  });

  router.delete('/:id', (req, res) => {
    const userId = sessionUserId(res);
    const row = loadAttachment(db, userId, String(req.params.id));
    db.prepare('DELETE FROM attachments WHERE id = ? AND user_id = ?').run(row.id, userId);
    try {
      fs.rmSync(attachmentFilePath(config, row.storage_key), { force: true });
    } catch (err) {
      console.error(err);
    }
    res.json({ ok: true });
  });

  return router;
}
