import { createRequire } from 'node:module';
import path from 'node:path';
import { strToU8, zipSync } from 'fflate';
import { Router } from 'express';
import PDFDocument from 'pdfkit';
import { HttpError, type AppContext, type Db } from '../app';
import { sessionUserId } from '../auth';
import { attachmentFilePath, contentDisposition } from './attachments';
import { UNTITLED_LABEL, loadTags, type DocNode } from './notes';

const nodeRequire = createRequire(import.meta.url);

function fontPath(): string {
  const pkg = nodeRequire.resolve('dejavu-fonts-ttf/package.json');
  return path.join(path.dirname(pkg), 'ttf', 'DejaVuSans.ttf');
}

// ---- TipTap JSON to Markdown ----

function escapeText(text: string): string {
  return text
    .replace(/([\\*`[\]])/g, '\\$1')
    .replace(/(^|[^\p{L}\p{N}])_|_(?=[^\p{L}\p{N}]|$)/gu, (match) => match.replace('_', '\\_'));
}

function markedText(node: DocNode): string {
  const text = node.text ?? '';
  const marks = node.marks ?? [];
  const lead = (/^\s*/.exec(text) as RegExpExecArray)[0];
  const rest = text.slice(lead.length);
  const trail = (/\s*$/.exec(rest) as RegExpExecArray)[0];
  let core = rest.slice(0, rest.length - trail.length);
  if (core === '') return text;
  const has = (type: string) => marks.some((mark) => mark.type === type);
  if (has('code')) {
    const ticks = core.includes('`') ? '``' : '`';
    core = ticks + (core.includes('`') ? ' ' + core + ' ' : core) + ticks;
  } else {
    core = escapeText(core);
  }
  if (has('italic')) core = '*' + core + '*';
  if (has('bold')) core = '**' + core + '**';
  if (has('strike')) core = '~~' + core + '~~';
  const link = marks.find((mark) => mark.type === 'link');
  if (link) {
    const href = String(link.attrs?.href ?? '').replace(
      /[()\s]/g,
      (char) => '%' + char.charCodeAt(0).toString(16).toUpperCase(),
    );
    core = '[' + core + '](' + href + ')';
  }
  return lead + core + trail;
}

function inlineMarkdown(nodes: DocNode[] | undefined): string {
  let out = '';
  for (const node of nodes ?? []) {
    if (node.type === 'hardBreak') out += '  \n';
    else if (node.type === 'text') out += markedText(node);
    else out += inlineMarkdown(node.content);
  }
  return out;
}

function plainContent(node: DocNode): string {
  if (node.type === 'text') return node.text ?? '';
  return (node.content ?? []).map(plainContent).join('');
}

function listMarkdown(node: DocNode): string {
  const start = typeof node.attrs?.start === 'number' ? node.attrs.start : 1;
  const items = (node.content ?? []).map((item, index) => {
    let marker = node.type === 'orderedList' ? start + index + '. ' : '- ';
    if (node.type === 'taskList' || item.type === 'taskItem') {
      marker = item.attrs?.checked === true ? '- [x] ' : '- [ ] ';
    }
    const pad = ' '.repeat(marker.length);
    const inner = blocksMarkdown(item.content)
      .split('\n')
      .map((line, lineIndex) => (lineIndex === 0 || line === '' ? line : pad + line))
      .join('\n');
    return marker + inner;
  });
  return items.join('\n');
}

function blockMarkdown(node: DocNode): string {
  switch (node.type) {
    case 'paragraph':
      return inlineMarkdown(node.content);
    case 'heading': {
      const level = typeof node.attrs?.level === 'number' ? node.attrs.level : 1;
      return '#'.repeat(level) + ' ' + inlineMarkdown(node.content);
    }
    case 'blockquote':
      return blocksMarkdown(node.content)
        .split('\n')
        .map((line) => (line === '' ? '>' : '> ' + line))
        .join('\n');
    case 'codeBlock': {
      const text = plainContent(node);
      const runs = text.match(/`+/g) ?? [];
      const fence = '`'.repeat(Math.max(3, ...runs.map((run) => run.length + 1)));
      const language = typeof node.attrs?.language === 'string' ? node.attrs.language : '';
      return fence + language + '\n' + text + '\n' + fence;
    }
    case 'horizontalRule':
      return '---';
    case 'bulletList':
    case 'orderedList':
    case 'taskList':
      return listMarkdown(node);
    default:
      return inlineMarkdown(node.content);
  }
}

function blocksMarkdown(nodes: DocNode[] | undefined): string {
  return (nodes ?? [])
    .map(blockMarkdown)
    .filter((block) => block !== '')
    .join('\n\n');
}

export function tiptapToMarkdown(doc: DocNode): string {
  return blocksMarkdown(doc.content) + '\n';
}

// ---- single-note export ----

function exportTitle(title: string): string {
  return title.trim() === '' ? UNTITLED_LABEL : title;
}

function fileBase(title: string): string {
  const cleaned = Array.from(exportTitle(title))
    .map((char) => (char.charCodeAt(0) < 32 || '\\/:*?"<>|'.includes(char) ? '_' : char))
    .join('')
    .trim()
    .slice(0, 80);
  return cleaned === '' ? 'note' : cleaned;
}

function renderPdf(title: string, bodyText: string): Promise<Buffer> {
  return new Promise<Buffer>((resolve, reject) => {
    const doc = new PDFDocument({ margin: 56 });
    const chunks: Buffer[] = [];
    doc.on('data', (chunk: Buffer) => chunks.push(chunk));
    doc.on('end', () => resolve(Buffer.concat(chunks)));
    doc.on('error', reject);
    try {
      doc.registerFont('Body', fontPath());
      doc.font('Body').fontSize(20).text(title);
      doc.moveDown();
      doc.fontSize(11).text(bodyText, { lineGap: 2 });
      doc.end();
    } catch (err) {
      reject(err);
    }
  });
}

export function noteExportRouter(ctx: AppContext): Router {
  const router = Router();
  const { db } = ctx;

  router.get('/:id/export', async (req, res) => {
    const userId = sessionUserId(res);
    const note = db
      .prepare('SELECT title, body_json, body_text FROM notes WHERE id = ? AND user_id = ?')
      .get(String(req.params.id), userId) as { title: string; body_json: string; body_text: string } | undefined;
    if (!note) throw new HttpError(404, 'Note not found');
    const format = typeof req.query.format === 'string' ? req.query.format : '';
    const title = exportTitle(note.title);
    const base = fileBase(note.title);
    res.setHeader('X-Content-Type-Options', 'nosniff');
    res.setHeader('Cache-Control', 'private, no-store');

    if (format === 'md') {
      const body = tiptapToMarkdown(JSON.parse(note.body_json) as DocNode);
      res.setHeader('Content-Type', 'text/markdown; charset=utf-8');
      res.setHeader('Content-Disposition', contentDisposition('attachment', base + '.md'));
      res.send('# ' + escapeText(title) + '\n\n' + body);
    } else if (format === 'txt') {
      res.setHeader('Content-Type', 'text/plain; charset=utf-8');
      res.setHeader('Content-Disposition', contentDisposition('attachment', base + '.txt'));
      res.send(title + '\n\n' + note.body_text + '\n');
    } else if (format === 'pdf') {
      const pdf = await renderPdf(title, note.body_text);
      res.setHeader('Content-Type', 'application/pdf');
      res.setHeader('Content-Disposition', contentDisposition('attachment', base + '.pdf'));
      res.send(pdf);
    } else {
      throw new HttpError(400, 'Choose a valid export format');
    }
  });

  return router;
}

// ---- full-collection ZIP (OD-018) ----

function folderPaths(db: Db, userId: string): Map<string, string[]> {
  const rows = db.prepare('SELECT id, parent_id, name FROM folders WHERE user_id = ?').all(userId) as {
    id: string;
    parent_id: string | null;
    name: string;
  }[];
  const byId = new Map(rows.map((row) => [row.id, row]));
  const paths = new Map<string, string[]>();
  for (const row of rows) {
    const segments: string[] = [];
    let current: (typeof rows)[number] | undefined = row;
    for (let guard = 0; current && guard < 100; guard += 1) {
      segments.unshift(current.name);
      current = current.parent_id ? byId.get(current.parent_id) : undefined;
    }
    paths.set(row.id, segments);
  }
  return paths;
}

function entryName(raw: string): string {
  const cleaned = Array.from(raw)
    .map((char) => (char.charCodeAt(0) < 32 || '\\/:*?"<>|'.includes(char) ? '_' : char))
    .join('')
    .trim()
    .slice(0, 60);
  return cleaned === '' ? 'note' : cleaned;
}

export function exportRouter(ctx: AppContext): Router {
  const router = Router();
  const { db, config } = ctx;

  router.get('/', (_req, res) => {
    const userId = sessionUserId(res);
    const notes = db
      .prepare(
        `SELECT id, title, body_json, folder_id, pinned FROM notes
         WHERE user_id = ? AND archived_at IS NULL AND trashed_at IS NULL ORDER BY created_at, rowid`,
      )
      .all(userId) as { id: string; title: string; body_json: string; folder_id: string | null; pinned: number }[];
    const paths = folderPaths(db, userId);
    const tags = loadTags(
      db,
      userId,
      notes.map((note) => note.id),
    );
    const files: Record<string, Uint8Array> = {};
    for (const note of notes) {
      const front = [
        '---',
        'id: ' + JSON.stringify(note.id),
        'title: ' + JSON.stringify(note.title),
        'folder: ' + JSON.stringify(note.folder_id ? (paths.get(note.folder_id) ?? []) : []),
        'tags: ' + JSON.stringify((tags.get(note.id) ?? []).map((tag) => tag.name)),
        'pinned: ' + (note.pinned === 1 ? 'true' : 'false'),
        '---',
        '',
      ].join('\n');
      const body = tiptapToMarkdown(JSON.parse(note.body_json) as DocNode);
      files['notes/' + entryName(note.title === '' ? UNTITLED_LABEL : note.title) + '-' + note.id + '.md'] = strToU8(
        front + '\n' + body,
      );

      const attachments = db
        .prepare('SELECT file_name, storage_key FROM attachments WHERE note_id = ? AND user_id = ? ORDER BY uploaded_at, rowid')
        .all(note.id, userId) as { file_name: string; storage_key: string }[];
      const used = new Set<string>();
      for (const attachment of attachments) {
        let data: Buffer;
        try {
          data = fs.readFileSync(attachmentFilePath(config, attachment.storage_key));
        } catch {
          continue;
        }
        let name = entryName(attachment.file_name);
        for (let n = 2; used.has(name); n += 1) name = n + '-' + entryName(attachment.file_name);
        used.add(name);
        files['attachments/' + note.id + '/' + name] = new Uint8Array(data);
      }
    }
    const zip = zipSync(files);
    res.setHeader('Content-Type', 'application/zip');
    res.setHeader('Content-Disposition', contentDisposition('attachment', 'team-notes-export.zip'));
    res.setHeader('X-Content-Type-Options', 'nosniff');
    res.setHeader('Cache-Control', 'private, no-store');
    res.send(Buffer.from(zip));
  });

  return router;
}
