import fs from 'node:fs';
import path from 'node:path';
import type { Readable } from 'node:stream';
import busboy from 'busboy';
import { unzipSync, type UnzipFileInfo } from 'fflate';
import { Router, type Request } from 'express';
import MarkdownIt from 'markdown-it';
import { HttpError, attachmentsDir, type AppContext, type Config, type Db } from '../app';
import { sessionUserId } from '../auth';
import { attachmentExtension, checkAttachmentType, sizeLimitMessage, TYPE_ERROR } from './attachments';
import { insertNote, validateBodyJson, type DocNode } from './notes';
import { findOrCreateTag, tagNameKey } from './tags';

const MAX_UPLOAD_FILE_BYTES = 100 * 1024 * 1024;
const MAX_UPLOAD_FILES = 200;
const MAX_NOTE_FILE_BYTES = 5 * 1024 * 1024;
const MAX_ARCHIVE_BYTES = 500 * 1024 * 1024;
const MAX_FOLDER_NAME = 200;
const REVIEW_TTL_MS = 15 * 60 * 1000;
const SAFE_LINK = /^(https?:|mailto:)/i;

type Token = ReturnType<MarkdownIt['parse']>[number];

interface PlanAttachment {
  fileName: string;
  mime: string;
  data: Uint8Array;
}

interface PlanNote {
  title: string;
  doc: DocNode;
  folderPath: string[];
  tags: string[];
  pinned: boolean;
  attachments: PlanAttachment[];
}

interface Counts {
  notes: number;
  folders: number;
  tags: number;
  attachments: number;
}

interface Plan {
  userId: string;
  expiresAt: number;
  notes: PlanNote[];
  counts: Counts;
}

interface Rejected {
  name: string;
  reason: string;
}

const plans = new Map<string, Plan>();

function sweepPlans(): void {
  const now = Date.now();
  for (const [token, plan] of plans) {
    if (plan.expiresAt <= now) plans.delete(token);
  }
}

function findPlan(token: unknown, userId: string): { token: string; plan: Plan } {
  sweepPlans();
  const plan = typeof token === 'string' ? plans.get(token) : undefined;
  if (typeof token !== 'string' || !plan || plan.userId !== userId) {
    throw new HttpError(404, 'This import review has expired. Review the files again.');
  }
  return { token, plan };
}

// ---- Markdown to TipTap ----

function inlineNodes(children: Token[]): DocNode[] {
  const out: DocNode[] = [];
  const stack: ({ type: string; attrs?: Record<string, unknown> } | null)[] = [];
  const push = (text: string, extra?: { type: string }): void => {
    if (text === '') return;
    const node: DocNode = { type: 'text', text };
    const marks = stack.filter((mark): mark is { type: string; attrs?: Record<string, unknown> } => mark !== null);
    if (extra) marks.push(extra);
    if (marks.length > 0) node.marks = marks;
    out.push(node);
  };
  for (const token of children) {
    switch (token.type) {
      case 'text':
        push(token.content);
        break;
      case 'code_inline':
        push(token.content, { type: 'code' });
        break;
      case 'softbreak':
      case 'hardbreak':
        out.push({ type: 'hardBreak' });
        break;
      case 'strong_open':
        stack.push({ type: 'bold' });
        break;
      case 'em_open':
        stack.push({ type: 'italic' });
        break;
      case 's_open':
        stack.push({ type: 'strike' });
        break;
      case 'link_open': {
        const href = token.attrGet('href') ?? '';
        stack.push(SAFE_LINK.test(href) && href.length <= 2048 ? { type: 'link', attrs: { href } } : null);
        break;
      }
      case 'strong_close':
      case 'em_close':
      case 's_close':
      case 'link_close':
        stack.pop();
        break;
      default:
        push(token.content);
    }
  }
  return out;
}

const CHECKBOX = /^\[([ xX])\][ \t]/;

function firstText(item: DocNode): DocNode | undefined {
  const paragraph = item.content?.[0];
  if (!paragraph || paragraph.type !== 'paragraph') return undefined;
  const text = paragraph.content?.[0];
  return text && text.type === 'text' ? text : undefined;
}

// A bullet list whose items all start with a checkbox becomes a task list.
function finalizeList(list: DocNode): void {
  if (list.type !== 'bulletList') return;
  const items = list.content ?? [];
  if (items.length === 0) return;
  if (!items.every((item) => CHECKBOX.test(firstText(item)?.text ?? ''))) return;
  list.type = 'taskList';
  for (const item of items) {
    const text = firstText(item) as DocNode;
    const match = CHECKBOX.exec(text.text ?? '') as RegExpExecArray;
    text.text = (text.text ?? '').slice(match[0].length);
    if (text.text === '') {
      const paragraph = item.content?.[0] as DocNode;
      paragraph.content = (paragraph.content ?? []).slice(1);
    }
    item.type = 'taskItem';
    item.attrs = { checked: match[1] !== ' ', item_key: randomUUID() };
  }
}

function markdownToDoc(md: MarkdownIt, source: string): DocNode {
  const root: DocNode = { type: 'doc', content: [] };
  const stack: DocNode[] = [root];
  const top = (): DocNode => stack[stack.length - 1];
  const append = (node: DocNode): void => {
    const parent = top();
    (parent.content ??= []).push(node);
  };
  const open = (node: DocNode): void => {
    node.content = [];
    append(node);
    stack.push(node);
  };
  for (const token of md.parse(source, {})) {
    switch (token.type) {
      case 'paragraph_open':
        open({ type: 'paragraph' });
        break;
      case 'heading_open':
        open({ type: 'heading', attrs: { level: Number(token.tag.slice(1)) || 1 } });
        break;
      case 'bullet_list_open':
        open({ type: 'bulletList' });
        break;
      case 'ordered_list_open': {
        const start = Number(token.attrGet('start') ?? 1);
        open({ type: 'orderedList', attrs: { start: Number.isInteger(start) ? start : 1 } });
        break;
      }
      case 'list_item_open':
        open({ type: 'listItem' });
        break;
      case 'blockquote_open':
        open({ type: 'blockquote' });
        break;
      case 'bullet_list_close':
      case 'ordered_list_close': {
        const list = stack.pop() as DocNode;
        finalizeList(list);
        break;
      }
      case 'paragraph_close':
      case 'heading_close':
      case 'list_item_close':
      case 'blockquote_close':
        stack.pop();
        break;
      case 'fence':
      case 'code_block': {
        const text = token.content.replace(/\n$/, '');
        const language = token.info.trim().split(/\s+/)[0];
        const node: DocNode = { type: 'codeBlock' };
        if (language !== '') node.attrs = { language };
        if (text !== '') node.content = [{ type: 'text', text }];
        append(node);
        break;
      }
      case 'hr':
        append({ type: 'horizontalRule' });
        break;
      case 'inline': {
        let target = top();
        if (target.type !== 'paragraph' && target.type !== 'heading') {
          const paragraph: DocNode = { type: 'paragraph', content: [] };
          append(paragraph);
          target = paragraph;
        }
        (target.content ??= []).push(...inlineNodes(token.children ?? []));
        break;
      }
      default:
        break;
    }
  }
  if (!root.content || root.content.length === 0) root.content = [{ type: 'paragraph' }];
  return root;
}

function textToDoc(text: string): DocNode {
  const paragraphs = text
    .replace(/\r\n?/g, '\n')
    .split(/\n{2,}/)
    .map((block) => block.split('\n').filter((line) => line !== ''))
    .filter((lines) => lines.length > 0)
    .map((lines): DocNode => {
      const content: DocNode[] = [];
      lines.forEach((line, index) => {
        if (index > 0) content.push({ type: 'hardBreak' });
        content.push({ type: 'text', text: line });
      });
      return { type: 'paragraph', content };
    });
  return { type: 'doc', content: paragraphs.length > 0 ? paragraphs : [{ type: 'paragraph' }] };
}

// ---- front matter ----

function parseValue(raw: string): unknown {
  try {
    return JSON.parse(raw);
  } catch {
    return raw.trim();
  }
}

function splitFrontMatter(text: string): { meta: Record<string, unknown>; body: string } {
  const normalized = text.replace(/\r\n?/g, '\n');
  if (!normalized.startsWith('---\n')) return { meta: {}, body: normalized };
  const end = normalized.indexOf('\n---', 3);
  if (end === -1) return { meta: {}, body: normalized };
  const after = normalized.slice(end + 4);
  if (after !== '' && !after.startsWith('\n')) return { meta: {}, body: normalized };
  const meta: Record<string, unknown> = {};
  for (const line of normalized.slice(4, Math.max(4, end)).split('\n')) {
    const match = /^([A-Za-z_]+):\s*(.*)$/.exec(line);
    if (match) meta[match[1]] = parseValue(match[2]);
  }
  return { meta, body: after.replace(/^\n+/, '') };
}

function stringList(value: unknown, separator: string): string[] {
  const items = Array.isArray(value) ? value : typeof value === 'string' ? value.split(separator) : [];
  return items
    .filter((item): item is string => typeof item === 'string')
    .map((item) => item.trim())
    .filter((item) => item !== '');
}

function baseName(fileName: string): string {
  const base = path.posix.basename(fileName.replace(/\\/g, '/'));
  const dot = base.lastIndexOf('.');
  return dot > 0 ? base.slice(0, dot) : base;
}

interface ParsedNote {
  note: PlanNote;
  sourceId: string | undefined;
}

function parseNoteFile(md: MarkdownIt, fileName: string, data: Uint8Array): ParsedNote {
  let text = new TextDecoder('utf-8').decode(data);
  if (text.startsWith('\uFEFF')) text = text.slice(1);
  if (text.includes('\u0000')) throw new HttpError(415, TYPE_ERROR);
  const isMarkdown = attachmentExtension(fileName) === 'md';
  const { meta, body } = isMarkdown ? splitFrontMatter(text) : { meta: {} as Record<string, unknown>, body: text };
  const doc = validateBodyJson(isMarkdown ? markdownToDoc(md, body) : textToDoc(body));
  if (Buffer.byteLength(JSON.stringify(doc), 'utf8') > MAX_NOTE_FILE_BYTES) {
    throw new HttpError(413, 'File is too large to import as a note');
  }
  const folder = Array.isArray(meta.folder) ? stringList(meta.folder, '/') : stringList(meta.folder, '/');
  return {
    sourceId: typeof meta.id === 'string' ? meta.id : undefined,
    note: {
      title: typeof meta.title === 'string' ? meta.title.slice(0, 500) : baseName(fileName).slice(0, 500),
      doc,
      folderPath: folder.map((segment) => segment.slice(0, MAX_FOLDER_NAME)),
      tags: stringList(meta.tags, ','),
      pinned: meta.pinned === true,
      attachments: [],
    },
  };
}

// ---- plan building ----

interface Upload {
  name: string;
  data: Uint8Array;
}

function receiveFiles(req: Request): Promise<{ files: Upload[]; rejected: Rejected[] }> {
  return new Promise((resolve, reject) => {
    let bb: busboy.Busboy;
    try {
      bb = busboy({
        headers: req.headers,
        defParamCharset: 'utf8',
        limits: { files: MAX_UPLOAD_FILES, fileSize: MAX_UPLOAD_FILE_BYTES, fields: 5 },
      });
    } catch {
      reject(new HttpError(400, 'Upload is not valid'));
      return;
    }
    const files: Upload[] = [];
    const rejected: Rejected[] = [];
    let failed = false;
    bb.on('file', (_field, stream: Readable, info) => {
      const name = path.posix.basename((info.filename ?? '').replace(/\\/g, '/')) || 'file';
      const chunks: Buffer[] = [];
      let truncated = false;
      stream.on('data', (chunk: Buffer) => chunks.push(chunk));
      stream.on('limit', () => {
        truncated = true;
      });
      stream.on('close', () => {
        if (truncated) rejected.push({ name, reason: 'File is too large to import' });
        else files.push({ name, data: new Uint8Array(Buffer.concat(chunks)) });
      });
    });
    bb.on('filesLimit', () => {
      rejected.push({ name: '(additional files)', reason: 'Too many files in one import' });
    });
    bb.on('error', () => {
      failed = true;
      reject(new HttpError(400, 'Upload is not valid'));
    });
    bb.on('close', () => {
      if (!failed) resolve({ files, rejected });
    });
    req.on('error', () => {
      failed = true;
      reject(new HttpError(400, 'Upload was interrupted'));
    });
    req.pipe(bb);
  });
}

function reasonFor(err: unknown): string {
  return err instanceof HttpError ? err.message : 'File could not be read';
}

function isUnsafeEntry(name: string): boolean {
  return name.startsWith('/') || name.includes('\\') || name.includes(':') || name.split('/').some((part) => part === '..');
}

function isIgnorableEntry(name: string): boolean {
  return name.endsWith('/') || name.startsWith('__MACOSX/') || path.posix.basename(name) === '.DS_Store';
}

function processZip(
  cfg: Config,
  md: MarkdownIt,
  upload: Upload,
  notes: PlanNote[],
  rejected: Rejected[],
): void {
  let total = 0;
  const filter = (file: UnzipFileInfo): boolean => {
    const name = file.name;
    if (isIgnorableEntry(name)) return false;
    if (isUnsafeEntry(name)) {
      rejected.push({ name, reason: 'Entry path is not allowed' });
      return false;
    }
    const isAttachment = name.startsWith('attachments/');
    if (!isAttachment) {
      const ext = attachmentExtension(name);
      if (ext !== 'md' && ext !== 'txt') {
        rejected.push({ name, reason: TYPE_ERROR });
        return false;
      }
    }
    const limit = isAttachment ? cfg.maxAttachmentBytes : MAX_NOTE_FILE_BYTES;
    if (file.originalSize > limit) {
      rejected.push({ name, reason: isAttachment ? sizeLimitMessage(cfg) : 'File is too large to import as a note' });
      return false;
    }
    total += file.originalSize;
    if (total > MAX_ARCHIVE_BYTES) {
      rejected.push({ name, reason: 'Archive is too large' });
      return false;
    }
    return true;
  };
  let entries: Record<string, Uint8Array>;
  try {
    entries = unzipSync(upload.data, { filter });
  } catch {
    rejected.push({ name: upload.name, reason: 'ZIP file could not be read' });
    return;
  }
  const names = Object.keys(entries).sort();
  const byId = new Map<string, PlanNote>();
  for (const name of names.filter((entry) => !entry.startsWith('attachments/'))) {
    try {
      const parsed = parseNoteFile(md, name, entries[name]);
      notes.push(parsed.note);
      if (parsed.sourceId !== undefined && !byId.has(parsed.sourceId)) byId.set(parsed.sourceId, parsed.note);
    } catch (err) {
      rejected.push({ name, reason: reasonFor(err) });
    }
  }
  for (const name of names.filter((entry) => entry.startsWith('attachments/'))) {
    const parts = name.split('/');
    const owner = parts.length >= 3 ? byId.get(parts[1]) : undefined;
    if (!owner) {
      rejected.push({ name, reason: 'No matching note for this attachment' });
      continue;
    }
    const fileName = parts[parts.length - 1];
    const type = checkAttachmentType(cfg, fileName, entries[name].subarray(0, 8192));
    if (!type) {
      rejected.push({ name, reason: TYPE_ERROR });
      continue;
    }
    owner.attachments.push({ fileName, mime: type.mime, data: entries[name] });
  }
}

// ---- folder resolution and counting ----

class FolderResolver {
  created = 0;
  private readonly known = new Map<string, string>();
  private readonly db: Db;
  private readonly userId: string;
  private readonly persist: boolean;

  constructor(db: Db, userId: string, persist: boolean) {
    this.db = db;
    this.userId = userId;
    this.persist = persist;
    const rows = db.prepare('SELECT id, parent_id, name FROM folders WHERE user_id = ?').all(userId) as {
      id: string;
      parent_id: string | null;
      name: string;
    }[];
    for (const row of rows) {
      const key = (row.parent_id ?? '') + '\u0000' + tagNameKey(row.name);
      if (!this.known.has(key)) this.known.set(key, row.id);
    }
  }

  resolve(segments: string[]): string | null {
    let parent: string | null = null;
    for (const segment of segments) {
      const key = (parent ?? '') + '\u0000' + tagNameKey(segment);
      let id = this.known.get(key);
      if (id === undefined) {
        this.created += 1;
        if (this.persist) {
          id = randomUUID();
          const next = this.db
            .prepare('SELECT COALESCE(MAX(position), -1) + 1 AS position FROM folders WHERE user_id = ? AND parent_id IS ?')
            .get(this.userId, parent) as { position: number };
          const now = Date.now();
          this.db
            .prepare(
              `INSERT INTO folders (id, user_id, parent_id, name, position, created_at, updated_at)
               VALUES (?, ?, ?, ?, ?, ?, ?)`,
            )
            .run(id, this.userId, parent, segment, next.position, now, now);
        } else {
          id = 'virtual:' + this.created;
        }
        this.known.set(key, id);
      }
      parent = id;
    }
    return parent;
  }
}

function computeCounts(db: Db, userId: string, notes: PlanNote[]): Counts {
  const folders = new FolderResolver(db, userId, false);
  for (const note of notes) folders.resolve(note.folderPath);
  const existing = new Set(
    (db.prepare('SELECT name_key FROM tags WHERE user_id = ?').all(userId) as { name_key: string }[]).map(
      (row) => row.name_key,
    ),
  );
  const newTags = new Set<string>();
  for (const note of notes) {
    for (const name of note.tags) {
      const key = tagNameKey(name);
      if (!existing.has(key)) newTags.add(key);
    }
  }
  return {
    notes: notes.length,
    folders: folders.created,
    tags: newTags.size,
    attachments: notes.reduce((sum, note) => sum + note.attachments.length, 0),
  };
}

function sameCounts(a: Counts, b: Counts): boolean {
  return a.notes === b.notes && a.folders === b.folders && a.tags === b.tags && a.attachments === b.attachments;
}

function executePlan(ctx: AppContext, plan: Plan): Counts {
  const { db, config } = ctx;
  const userId = plan.userId;
  const created: Counts = { notes: 0, folders: 0, tags: 0, attachments: 0 };
  const written: string[] = [];
  const run = db.transaction(() => {
    const folders = new FolderResolver(db, userId, true);
    for (const note of plan.notes) {
      const folderId = folders.resolve(note.folderPath);
      const noteId = insertNote(db, userId, {
        title: note.title,
        doc: note.doc,
        folderId,
        pinned: note.pinned,
        now: Date.now(),
      });
      created.notes += 1;
      for (const name of note.tags) {
        const tag = findOrCreateTag(db, userId, name);
        if (tag.created) created.tags += 1;
        db.prepare('INSERT OR IGNORE INTO note_tags (note_id, tag_id, user_id) VALUES (?, ?, ?)').run(
          noteId,
          tag.id,
          userId,
        );
      }
      for (const attachment of note.attachments) {
        const key = randomUUID();
        fs.mkdirSync(attachmentsDir(config), { recursive: true });
        const file = path.join(attachmentsDir(config), key);
        fs.writeFileSync(file, attachment.data);
        written.push(file);
        db.prepare(
          `INSERT INTO attachments (id, user_id, note_id, file_name, mime, size, storage_key, uploaded_at)
           VALUES (?, ?, ?, ?, ?, ?, ?, ?)`,
        ).run(randomUUID(), userId, noteId, attachment.fileName, attachment.mime, attachment.data.length, key, Date.now());
        created.attachments += 1;
      }
    }
    created.folders = folders.created;
  });
  try {
    run();
  } catch (err) {
    for (const file of written) fs.rmSync(file, { force: true });
    throw err;
  }
  return created;
}

export function importRouter(ctx: AppContext): Router {
  const router = Router();
  const { db, config } = ctx;
  const md = new MarkdownIt({ html: false, linkify: false });

  router.post('/review', async (req, res) => {
    const userId = sessionUserId(res);
    if (!/^multipart\/form-data/i.test(req.headers['content-type'] ?? '')) {
      throw new HttpError(400, 'Upload is not valid');
    }
    const { files, rejected } = await receiveFiles(req);
    if (files.length === 0 && rejected.length === 0) throw new HttpError(400, 'No files were uploaded');

    const notes: PlanNote[] = [];
    for (const file of files) {
      const ext = attachmentExtension(file.name);
      if (ext === 'zip') {
        processZip(config, md, file, notes, rejected);
      } else if (ext === 'md' || ext === 'txt') {
        if (file.data.length > MAX_NOTE_FILE_BYTES) {
          rejected.push({ name: file.name, reason: 'File is too large to import as a note' });
          continue;
        }
        try {
          notes.push(parseNoteFile(md, file.name, file.data).note);
        } catch (err) {
          rejected.push({ name: file.name, reason: reasonFor(err) });
        }
      } else {
        rejected.push({ name: file.name, reason: TYPE_ERROR });
      }
    }

    sweepPlans();
    const counts = computeCounts(db, userId, notes);
    const token = randomBytes(24).toString('base64url');
    plans.set(token, { userId, expiresAt: Date.now() + REVIEW_TTL_MS, notes, counts });
    res.json({ token, counts, rejected });
  });

  router.post('/confirm', (req, res) => {
    const userId = sessionUserId(res);
    const { token, plan } = findPlan(req.body?.token, userId);
    const current = computeCounts(db, userId, plan.notes);
    if (!sameCounts(current, plan.counts)) {
      plans.delete(token);
      throw new HttpError(409, 'Your folders or tags changed since the review. Review the import again.');
    }
    const created = executePlan(ctx, plan);
    plans.delete(token);
    res.json({ created });
  });

  router.delete('/:token', (req, res) => {
    const { token } = findPlan(req.params.token, sessionUserId(res));
    plans.delete(token);
    res.json({ ok: true });
  });

  return router;
}
